import { getLocale } from "next-intl/server";

import { redirect } from "@/i18n/navigation";

/**
 * `/chat` landing — redirects into a freshly-minted conversation id.
 *
 * No `conversations` row is created here. The row is created lazily
 * by `app/api/chat/route.ts` on the first POST for this id, so
 * visiting `/chat` and then never sending a message leaves nothing
 * behind (conversations are a persistence concern the route
 * owns, not a page-load side effect).
 */
export default async function ChatIndexPage() {
  const locale = await getLocale();
  redirect({ href: `/chat/${crypto.randomUUID()}`, locale });
}

import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";

import { ChatWorkspace } from "@/components/chat/chat-workspace";
import { ConversationHeader } from "@/components/chat/conversation-header";
import { loadConversationForChat } from "@/actions/chat";
import { getChatModelOptions } from "@/lib/chat-models";
import { getChatQuotaState } from "@/lib/chat-quota";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("chat");
  return { title: t("conversationPage.title") };
}

/**
 * `dynamic = "force-dynamic"`: `loadConversationForChat` reads
 * request-scoped session and workspace state (`requireWorkspace()`,
 * inside `@/actions/chat`), so this page can only ever render
 * per-request. History is the shell's (`ChatHistory` in the sidebar).
 */
export const dynamic = "force-dynamic";

interface ConversationPageProps {
  params: Promise<{ id: string; locale: string }>;
}

export default async function ConversationPage({
  params,
}: ConversationPageProps) {
  const { id } = await params;
  const t = await getTranslations("chat");
  const { workspace } = await requireWorkspace();

  // In parallel: the quota read is an estimate that holds no credit,
  // so it cannot slow down or interfere with loading the conversation.
  const [conversationResult, quotaState, models] = await Promise.all([
    loadConversationForChat(id),
    getChatQuotaState(),
    getChatModelOptions(workspace.id),
  ]);

  if (!conversationResult.success) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 p-8 text-center">
        <h1 className="text-lg font-semibold">
          {t("conversationPage.unavailableTitle")}
        </h1>
        <p className="text-sm text-muted-foreground">
          {conversationResult.error}
        </p>
      </div>
    );
  }

  const { conversation, messages, votes } = conversationResult.data;

  return (
    <div className="flex h-full min-h-0 flex-col">
      <ConversationHeader
        conversationId={id}
        title={conversation?.title ?? null}
      />
      <ChatWorkspace
        conversationId={id}
        initialMessages={messages}
        quotaState={quotaState}
        votes={votes}
        models={models}
      />
    </div>
  );
}

import { Skeleton } from "@/components/ui/skeleton";

export default function ConversationLoading() {
  return (
    <div className="flex h-full flex-col">
      <div className="flex-1 space-y-6 px-4 py-6">
        <div className="mx-auto flex max-w-3xl flex-col gap-6">
          <Skeleton className="ml-auto h-10 w-2/3 rounded-2xl" />
          <Skeleton className="h-24 w-3/4 rounded-lg" />
          <Skeleton className="ml-auto h-10 w-1/2 rounded-2xl" />
        </div>
      </div>
    </div>
  );
}

"use client";

/**
 * Error boundary for a chat conversation. Renders the shared `RouteError` from the
 * `route-error` item — install it alongside this one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return (
    <RouteError
      error={error}
      reset={reset}
      scope="chat-conversation"
      fallback="conversation"
      homeHref="/chat"
      homeKey="goToChat"
    />
  );
}

"use server";

/**
 * Chat conversation actions — thin transport over
 * `@intelligo-dev/core/conversations`: resolve the caller's actor
 * via `requireWorkspace()`, call the core service, map any
 * `ConversationServiceError` to a friendly message, and reshape the
 * result for the page and its client components. Sending a message and
 * streaming a reply is NOT here — that is `app/api/chat/route.ts`,
 * because streaming needs a Route Handler, not a Server Action.
 *
 * `loadConversationForChat` is the one read that treats `not_found` as
 * success rather than failure: `app/[locale]/(app)/chat/page.tsx`
 * redirects to `/chat/<uuid>` without creating a row (see its doc
 * comment), so the very first render of a brand-new conversation
 * legitimately has no `conversations` row yet — the route handler
 * creates it on the first POST. Every other action here treats
 * `not_found`/`forbidden` as a genuine failure.
 */

import { getTranslations } from "next-intl/server";
import { revalidatePath } from "next/cache";

import { requireWorkspace } from "@intelligo-dev/auth";
import { recordChatFeedback, toUIMessages } from "@intelligo-dev/chat";
import {
  getDocumentVersions,
  isDocumentServiceError,
  saveDocument,
} from "@intelligo-dev/core/documents";
import {
  deleteConversation as deleteConversationRow,
  getConversation,
  getMessages,
  getVotes,
  isConversationServiceError,
  listConversations,
  renameConversation as renameConversationRow,
  setConversationVisibility,
  updateConversationMetadata,
} from "@intelligo-dev/core/conversations";

import { chatServerConfig } from "@/lib/chat-server-config";

export type ChatActionResult<T> =
  { success: true; data: T } | { success: false; error: string };

type Translator = Awaited<ReturnType<typeof getTranslations>>;

function friendlyMessageKey(code: string): string | undefined {
  switch (code) {
    case "not_found":
      return "actions.conversationNotFound";
    case "forbidden":
      return "actions.conversationForbidden";
    case "invalid_input":
      return "actions.invalidTitle";
    case "database_error":
      return "actions.databaseError";
    default:
      return undefined;
  }
}

function friendlyError(t: Translator, error: unknown): string {
  // Unknown errors deliberately map to the generic key — a raw
  // `Error#message` can carry internals (SQL, hostnames) to the UI.
  if (isConversationServiceError(error) || isDocumentServiceError(error)) {
    const key = friendlyMessageKey(error.code);
    return key ? t(key) : t("actions.genericError");
  }
  return t("actions.genericError");
}

async function actor() {
  const { workspace, user } = await requireWorkspace();
  return { workspaceId: workspace.id, userId: user.id };
}

export type ConversationSummary = {
  id: string;
  title: string | null;
  updatedAt: string;
  pinned: boolean;
};

/** Recent conversations for the sidebar, most recently updated first. */
export async function listConversationHistory(): Promise<
  ChatActionResult<ConversationSummary[]>
> {
  try {
    // Enough to fill a sidebar and be worth searching. The cap is
    // deliberate: past a few hundred, filtering belongs in a query,
    // not in the browser (see `components/chat/chat-history-nav.tsx`).
    const rows = await listConversations(await actor(), { limit: 100 });
    return {
      success: true,
      data: rows.map((row) => ({
        id: row.id,
        title: row.title,
        updatedAt: row.updatedAt.toISOString(),
        pinned: (row.metadata as { pinned?: unknown } | null)?.pinned === true,
      })),
    };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export type LoadedConversation = {
  conversation: { id: string; title: string | null } | null;
  messages: ReturnType<typeof toUIMessages>;
  /** The reader's votes, by message id. */
  votes: Record<string, "up" | "down">;
};

/**
 * Loads a conversation and its messages for the thread's initial
 * state. A conversation id with no row yet resolves as a brand-new,
 * empty chat rather than an error — see the module doc comment above.
 */
export async function loadConversationForChat(
  id: string
): Promise<ChatActionResult<LoadedConversation>> {
  try {
    const scoped = await actor();

    try {
      const conversation = await getConversation(scoped, id);
      const [rows, voteRows] = await Promise.all([
        getMessages(scoped, id),
        getVotes(scoped, id),
      ]);
      const votes: Record<string, "up" | "down"> = {};
      for (const vote of voteRows) {
        votes[vote.messageId] = vote.isUpvoted ? "up" : "down";
      }
      return {
        success: true,
        data: {
          conversation: { id: conversation.id, title: conversation.title },
          // Stored parts are a JSON string; a corrupt row costs one
          // message, not the conversation.
          messages: toUIMessages(rows),
          votes,
        },
      };
    } catch (error) {
      if (isConversationServiceError(error) && error.code === "not_found") {
        return {
          success: true,
          data: { conversation: null, messages: [], votes: {} },
        };
      }
      throw error;
    }
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export async function renameConversation(
  id: string,
  title: string
): Promise<ChatActionResult<{ title: string | null }>> {
  try {
    const updated = await renameConversationRow(await actor(), id, title);
    return { success: true, data: { title: updated.title } };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export async function deleteConversation(
  id: string
): Promise<ChatActionResult<undefined>> {
  try {
    await deleteConversationRow(await actor(), id);
    return { success: true, data: undefined };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

/** Pin a conversation to the top of the sidebar, or unpin it. */
export async function setConversationPinned(
  id: string,
  pinned: boolean
): Promise<ChatActionResult<undefined>> {
  try {
    await updateConversationMetadata(await actor(), id, { pinned });
    return { success: true, data: undefined };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

/** The reader's verdict on a reply; `null` withdraws it. */
export async function voteMessage(
  conversationId: string,
  messageId: string,
  vote: "up" | "down" | null
): Promise<ChatActionResult<undefined>> {
  const t = await getTranslations("chat");
  try {
    const result = await recordChatFeedback(chatServerConfig, await actor(), {
      conversationId,
      messageId,
      vote,
    });
    if (!result.ok) {
      return {
        success: false,
        error: t(
          result.code === "not_found"
            ? "actions.conversationNotFound"
            : "actions.feedbackFailed"
        ),
      };
    }
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: friendlyError(t, error) };
  }
}

/** Whether the conversation is published at `/share/<id>`. */
export async function getShareState(
  id: string
): Promise<ChatActionResult<{ shared: boolean }>> {
  try {
    const row = await getConversation(await actor(), id);
    return { success: true, data: { shared: row.visibility === "public" } };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export async function setConversationShared(
  id: string,
  shared: boolean
): Promise<ChatActionResult<{ shared: boolean }>> {
  try {
    const row = await setConversationVisibility(
      await actor(),
      id,
      shared ? "public" : "private"
    );
    revalidatePath(`/share/${id}`);
    return { success: true, data: { shared: row.visibility === "public" } };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

/**
 * Saves one assistant reply as a document artifact, so a useful answer
 * doesn't only live in a conversation. This is the manual counterpart
 * to a `saveArtifact` tool: same destination (`@intelligo-dev/core`'s
 * document persistence), same `/artifacts` page, just driven
 * by the reader instead of the model.
 *
 * The message id becomes the document id, which makes saving the same
 * reply twice a new *version* of one artifact rather than a duplicate.
 */
export async function saveMessageAsArtifact(params: {
  messageId: string;
  content: string;
  title?: string;
  /** Lets the artifacts page link back to where this came from. */
  conversationId?: string;
}): Promise<ChatActionResult<{ id: string; title: string }>> {
  const t = await getTranslations("chat");

  const content = params.content.trim();
  if (!content) {
    return { success: false, error: t("actions.emptyArtifact") };
  }

  const title = params.title?.trim() || deriveArtifactTitle(content);

  try {
    const saved = await saveDocument(await actor(), {
      id: params.messageId,
      title,
      content,
      kind: "text",
      ...(params.conversationId
        ? { conversationId: params.conversationId }
        : {}),
    });
    revalidatePath("/artifacts");
    return { success: true, data: { id: saved.id, title: saved.title } };
  } catch (error) {
    return { success: false, error: friendlyError(t, error) };
  }
}

/** Every version of a document the canvas shows, newest first. */
export async function listArtifactVersions(
  documentId: string
): Promise<ChatActionResult<Array<{ createdAt: string; content: string }>>> {
  try {
    const versions = await getDocumentVersions(await actor(), documentId);
    return {
      success: true,
      data: versions.map((version) => ({
        createdAt: version.createdAt,
        content: version.content ?? "",
      })),
    };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

/** An edit in the canvas becomes a new version of the document. */
export async function saveArtifactVersion(params: {
  documentId: string;
  title: string;
  kind: string;
  content: string;
}): Promise<ChatActionResult<{ id: string }>> {
  const t = await getTranslations("chat");
  try {
    const saved = await saveDocument(await actor(), {
      id: params.documentId,
      title: params.title,
      content: params.content,
      kind: params.kind,
    });
    revalidatePath("/artifacts");
    return { success: true, data: { id: saved.id } };
  } catch (error) {
    return { success: false, error: friendlyError(t, error) };
  }
}

const MAX_ARTIFACT_TITLE = 60;

/** First line of the reply, trimmed to something list-sized. */
function deriveArtifactTitle(content: string): string {
  const line =
    content
      .split("\n")
      .map((value) => value.replace(/^#+\s*/, "").trim())
      .find(Boolean) ?? "";
  if (!line) return "Untitled";
  return line.length <= MAX_ARTIFACT_TITLE
    ? line
    : `${line.slice(0, MAX_ARTIFACT_TITLE - 1).trimEnd()}…`;
}

import "server-only";

/**
 * Consumer-owned model resolution for the chat transport.
 *
 * A fresh install has no AI provider keys, so `getChatModel` returns
 * the framework's deterministic stub (`@intelligo-dev/chat/testing`): it
 * echoes the last user message back through a real token-by-token
 * stream. No network call, no API key, and the app still builds,
 * boots and streams a real `createUIMessageStream` response end to end.
 *
 * `CHAT_MODEL_ID` is deliberately a real, registered id
 * (`@intelligo-dev/executions/pricing`) even though the stub never calls
 * that provider: the execution boundary bills whatever id the transport
 * settles with, and an id with no registered price is
 * refused at admission. Using a real id here means a clean install
 * exercises the *correct* pricing path — swap in your own model id the
 * moment you swap in a real provider below, and keep it one that is
 * registered.
 *
 * To use a real provider: install its AI SDK package (e.g.
 * `pnpm add @ai-sdk/anthropic` in this app) and replace the body of
 * `getChatModel` — the commented example below is the whole change.
 */

import type { LanguageModel } from "ai";
import { createStubLanguageModel } from "@intelligo-dev/chat/testing";
import { cookies } from "next/headers";
import { getTranslations } from "next-intl/server";

import { routing } from "@/i18n/routing";

/** Must be a registered model id in `@intelligo-dev/executions/pricing`. */
export const CHAT_MODEL_ID = "google/gemini-2.5-flash";

/**
 * The stub replies in the caller's locale. This file lives outside the
 * `[locale]` segment, so the locale comes from the `NEXT_LOCALE` cookie
 * next-intl's middleware sets on every page navigation.
 */
async function resolveLocale(): Promise<string> {
  const cookieName =
    typeof routing.localeCookie === "object"
      ? (routing.localeCookie.name ?? "NEXT_LOCALE")
      : "NEXT_LOCALE";
  const value = (await cookies()).get(cookieName)?.value;
  const locales: readonly string[] = routing.locales;
  return value && locales.includes(value) ? value : routing.defaultLocale;
}

/**
 * Resolves the language model for a chat turn. `modelId` is unused by
 * the stub (it only ever returns one model) — a real implementation
 * switches on it, e.g.:
 *
 *   import { anthropic } from "@ai-sdk/anthropic";
 *
 *   export function getChatModel(modelId: string): LanguageModel {
 *     if (modelId === CHAT_MODEL_ID) return anthropic("claude-sonnet-4-6-20260214");
 *     return anthropic("claude-sonnet-4-6-20260214");
 *   }
 *
 * and `CHAT_MODEL_ID` above becomes whatever registered id matches the
 * provider model string you pass.
 */
export function getChatModel(modelId: string): LanguageModel {
  void modelId;
  return createStubLanguageModel({
    modelId: CHAT_MODEL_ID,
    reply: async (userText) => {
      const t = await getTranslations({
        locale: await resolveLocale(),
        namespace: "chat",
      });
      return `${t("stub.preface")}\n\n${t("stub.youSaid")} "${userText}"`;
    },
  });
}

import "server-only";

/**
 * The models the composer offers — consumer-owned.
 *
 * Empty (the default) means the picker is hidden and every turn runs
 * on `lib/chat-model.ts`'s default. List two or more and the composer
 * shows a picker; the transport refuses anything not on the list, and
 * a model with a `featureKey` only to plans that have it. Every id
 * must be registered in `@intelligo-dev/executions/pricing` — an
 * architecture test holds this file to that.
 *
 *   export const CHAT_MODELS: ChatModelOption[] = [
 *     { id: "google/gemini-2.5-flash", label: "Fast" },
 *     { id: "anthropic/claude-sonnet-4-6", label: "Smart", featureKey: PRO_MODELS },
 *   ];
 *
 * Bind the same list in `lib/chat-server-config.ts` (`models`), which
 * is what makes the server's answer match the composer's offer.
 */

import { hasFeature } from "@intelligo-dev/billing";
import type { ChatModelOption } from "@intelligo-dev/chat/client";

export type { ChatModelOption };

export const CHAT_MODELS: ChatModelOption[] = [];

/** The models this workspace may pick from — the list, minus what its plan lacks. */
export async function getChatModelOptions(
  workspaceId: string
): Promise<ChatModelOption[]> {
  const allowed = await Promise.all(
    CHAT_MODELS.map(async (model) =>
      model.featureKey ? hasFeature(workspaceId, model.featureKey) : true
    )
  );
  return CHAT_MODELS.filter((_, index) => allowed[index]);
}

"use client";

/**
 * How a tool, and any runtime's data part, shows up in the chat.
 *
 * This is the extension point a product uses most. Adding a tool to
 * the agent is one entry in `TOOL_RENDERERS` below — a plain object
 * literal in source you own; there is no `register()` call, nothing
 * runs as an import side effect, and a product package's
 * card compiles against the structural props here rather than against
 * the AI SDK's types.
 *
 * A tool call is either a row in the activity stream — the one-line
 * "Searched the web ▸" the agent's work folds into — or its own card.
 * A tool with no entry is a row. An entry is a component (a card), or
 * `{ component?, label?, activity?, sources?, canvas? }`:
 *
 *   - `component` draws the call as its own card, in every state the
 *     SDK has (`input-streaming` → `output-available`, and the approval
 *     states of a gated tool). Without one the call is a row.
 *   - `label` is a message key naming the call in its row and in the
 *     stream's status line, in place of the tool's raw name
 *     ("Generating report…").
 *   - `activity` builds the call's row when the default is not enough.
 *     The default reads the input's first string as the target, and a
 *     call whose input has a `query` renders as a search, its results
 *     from `sources`.
 *   - `sources` reads the sources the call's output carries, which
 *     become the answer's citations. The default reads `output.sources`
 *     (`{ url, title?, domain?, snippet?, index? }[]`).
 *   - `canvas` says the tool's output also lives in the side panel
 *     (`lib/chat-canvas-config.tsx` decides how a `kind` renders). A
 *     document the tool streams with `createArtifactWriter` opens the
 *     canvas by itself; a card's Open reopens it.
 *
 * `actions` is what a card can do back to the conversation: send the
 * next user turn (a quiz option, a suggested reply), answer a tool
 * that runs client-side, approve or deny a gated call, open or close
 * the canvas.
 *
 * `DATA_RENDERERS` is the same seam for `data-*` parts — what a
 * Mastra workflow, an eve subagent or a product's own `turn.write`
 * emits. The framework's `data-chat-*` parts have renderers in
 * `components/chat/data-parts.tsx`; Mastra's arrive under their own
 * names and render on the activity timeline.
 */

import type { ComponentType } from "react";
import type { FileUIPart } from "ai";
import { useTranslations } from "next-intl";

import { ArtifactCard } from "@/components/chat/artifact-card";
import type {
  AgentActivitySearch,
  AgentActivityTool,
} from "@/components/ui/ai-agent-activity";
import { FileDiff, type FileDiffLine } from "@/components/ui/ai-file-diff";
import {
  ImageGeneration,
  type ImageGenerationStatus,
} from "@/components/ui/ai-image-generation";
import {
  ToolResult,
  ToolResultOutput,
  type ToolResultStatus,
} from "@/components/ui/ai-tool-result";
import type { SourceItem } from "@/lib/message-parts";

import {
  ChatAgentCard,
  ChatArtifactCard,
  ChatAuthorizationCard,
  ChatQuestionCard,
  ChatTaskCard,
} from "@/components/chat/data-parts";
import {
  MastraNetworkActivity,
  MastraToolAgentActivity,
  MastraToolAgentStepActivity,
  MastraWorkflowActivity,
  MastraWorkflowStepActivity,
} from "@/components/chat/agent-activity";

/**
 * Mirrors the AI SDK's `ToolUIPart`/`DynamicToolUIPart` state union
 * structurally rather than importing it, so a product package does
 * not pin itself to the SDK's exact tool generics. The three
 * `approval-*`/`output-denied` states only appear for tools using the
 * SDK's human-in-the-loop approval flow — a plain tool never produces
 * them.
 */
export type ToolPartState =
  | "input-streaming"
  | "input-available"
  | "approval-requested"
  | "approval-responded"
  | "output-available"
  | "output-error"
  | "output-denied";

/** What opens in the canvas. */
export type CanvasRef = {
  /** Stable across streamed updates — the artifact part's id or the document id. */
  id: string;
  kind: string;
  title: string;
  documentId?: string;
  /** Content already in hand, so the panel can open without a fetch. */
  content?: string;
  status?: "streaming" | "ready" | "error";
};

/** What a renderer can do back to the conversation. */
export interface ToolRendererActions {
  /** Send the next user turn — a picked option, a suggested reply. */
  sendMessage: (
    message: string | { text: string; files?: FileUIPart[] }
  ) => void;
  /** Answer a tool the client executes. */
  addToolResult: (args: {
    tool: string;
    toolCallId: string;
    output: unknown;
  }) => void;
  /** Approve or deny a gated call; the SDK continues the turn. */
  addToolApprovalResponse: (args: {
    id: string;
    approved: boolean;
    reason?: string;
  }) => void;
  openCanvas: (ref: CanvasRef) => void;
  closeCanvas: () => void;
}

export interface ToolRendererProps {
  toolName: string;
  state: ToolPartState;
  input?: unknown;
  output?: unknown;
  errorText?: string;
  /** The AI SDK's id for this call — required by `addToolResult`. */
  toolCallId?: string;
  /** Set while the call awaits or received an approval. */
  approvalId?: string;
  messageId: string;
  /** The message this part belongs to is still streaming. */
  isStreaming: boolean;
  /** A read-only surface — the shared page. Cards hide their controls. */
  isReadonly: boolean;
  actions?: ToolRendererActions;
}

/** A call's row in the activity stream; the stream assigns the id. */
export type ToolActivityRow =
  Omit<AgentActivitySearch, "id"> | Omit<AgentActivityTool, "id">;

export interface ToolRenderer {
  /** Draws the call as its own card. Without one the call is a row in the activity stream. */
  component?: ComponentType<ToolRendererProps>;
  /** A message key (namespace-less, like `chatConfig.starters`) naming the call. */
  label?: string;
  /** The call's row, when the default row is not enough. `null` keeps the default. */
  activity?: (props: ToolRendererProps) => ToolActivityRow | null;
  /** The sources the call's output carries. Default: `output.sources`. */
  sources?: (output: unknown) => SourceItem[];
  /**
   * The tool's output also lives in the canvas, as this kind, when its
   * result does not say. A document the tool streams through
   * `createArtifactWriter` opens the canvas by itself.
   */
  canvas?: { kind: string };
}

export interface DataRendererProps {
  /** The part name without the `data-` prefix. */
  name: string;
  id?: string;
  data: unknown;
  messageId: string;
  isStreaming: boolean;
  isReadonly: boolean;
  actions?: ToolRendererActions;
}

/**
 * Tool name → how its call renders.
 *
 * Ships with one entry: `saveArtifact`, the convention this catalogue
 * uses for "the assistant produced a document." Its card links into
 * the `artifacts` page and opens the document in the canvas.
 *
 * Add your own the same way:
 *
 *   import { WeatherCard } from "@/components/chat/tools/weather-card";
 *
 *   export const TOOL_RENDERERS: Record<string, ToolRenderer | ComponentType<ToolRendererProps>> = {
 *     saveArtifact: { component: ArtifactLinkCard, canvas: { kind: "text" } },
 *     applyPatch: FileDiffCard,        // any tool that returns a diff
 *     createImage: ImageGenerationCard, // any tool that returns an image
 *     getWeather: WeatherCard,
 *     lookupInvoice: { label: "invoices.lookingUp" },
 *     generateReport: { component: ReportCard, label: "reports.generating", canvas: { kind: "text" } },
 *   };
 */
export const TOOL_RENDERERS: Record<
  string,
  ToolRenderer | ComponentType<ToolRendererProps>
> = {
  saveArtifact: { component: ArtifactLinkCard, canvas: { kind: "text" } },
  editFile: FileDiffCard,
  generateImage: ImageGenerationCard,
};

/**
 * `data-*` part name (without the prefix) → its renderer. The
 * framework's own parts and Mastra's are shipped; a product adds the
 * parts its tools write with `turn.write`.
 */
export const DATA_RENDERERS: Record<
  string,
  ComponentType<DataRendererProps>
> = {
  "chat-task": ChatTaskCard,
  "chat-agent": ChatAgentCard,
  "chat-artifact": ChatArtifactCard,
  "chat-question": ChatQuestionCard,
  "chat-authorization": ChatAuthorizationCard,
  workflow: MastraWorkflowActivity,
  "workflow-step": MastraWorkflowStepActivity,
  network: MastraNetworkActivity,
  "tool-agent": MastraToolAgentActivity,
  "tool-agent-step": MastraToolAgentStepActivity,
};

export function resolveToolRenderer(
  toolName: string
): ToolRenderer & { component: ComponentType<ToolRendererProps> } {
  const entry = TOOL_RENDERERS[toolName];
  if (!entry) return { component: DefaultToolCard };
  if (typeof entry === "function") return { component: entry };
  return { ...entry, component: entry.component ?? DefaultToolCard };
}

/** Whether a tool has an entry of its own. */
export function hasToolRenderer(toolName: string): boolean {
  return toolName in TOOL_RENDERERS;
}

/** Whether a tool's call draws its own card rather than a row in the activity stream. */
export function hasToolCard(toolName: string): boolean {
  const entry = TOOL_RENDERERS[toolName];
  if (!entry) return false;
  return typeof entry === "function" || Boolean(entry.component);
}

/** The component a tool's call renders with. */
export function getToolRenderer(
  toolName: string
): ComponentType<ToolRendererProps> {
  return resolveToolRenderer(toolName).component;
}

export function getDataRenderer(
  name: string
): ComponentType<DataRendererProps> | null {
  return DATA_RENDERERS[name] ?? null;
}

/** Maps a tool part's state to its `chat.toolCard.*` message key. */
const STATE_MESSAGE_KEY: Record<ToolPartState, string> = {
  "input-streaming": "toolCard.calling",
  "input-available": "toolCard.running",
  "approval-requested": "toolCard.needsApproval",
  "approval-responded": "toolCard.approved",
  "output-available": "toolCard.done",
  "output-error": "toolCard.error",
  "output-denied": "toolCard.denied",
};

const TOOL_RESULT_STATUS: Record<ToolPartState, ToolResultStatus> = {
  "input-streaming": "running",
  "input-available": "running",
  "approval-requested": "running",
  "approval-responded": "running",
  "output-available": "success",
  "output-error": "error",
  "output-denied": "cancelled",
};

/** `webSearch` → "Web search". */
export function toolLabel(toolName: string): string {
  const spaced = toolName
    .replace(/[_-]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2");
  return spaced.charAt(0).toUpperCase() + spaced.slice(1).toLowerCase();
}

/**
 * The call with its raw input and output. The activity stream shows
 * this under a row the reader opens; a card that has nothing better to
 * show yet can draw it too.
 */
export function DefaultToolCard({
  toolName,
  state,
  input,
  output,
  errorText,
}: ToolRendererProps) {
  const t = useTranslations("chat");
  const status = TOOL_RESULT_STATUS[state];
  const outputText =
    errorText ??
    (output === undefined
      ? undefined
      : typeof output === "string"
        ? output
        : JSON.stringify(output, null, 2));

  return (
    <ToolResult
      className="max-w-xl"
      tool={toolName}
      title={toolLabel(toolName)}
      status={status}
      kind="custom"
      statusLabels={{
        running: t(STATE_MESSAGE_KEY[state]),
        success: t("toolCard.done"),
        error: t("toolCard.error"),
        cancelled: t("toolCard.denied"),
      }}
      copyLabel={t("actions.copy")}
      copiedLabel={t("actions.copied")}
      copyText={outputText}
    >
      {input !== undefined ? (
        <div className="grid gap-1 px-3 pt-2">
          <span className="text-xs font-medium text-muted-foreground">
            {t("toolCard.input")}
          </span>
          <ToolResultOutput language="json">
            {typeof input === "string" ? input : JSON.stringify(input, null, 2)}
          </ToolResultOutput>
        </div>
      ) : null}
      {outputText !== undefined ? (
        <div className="grid gap-1 px-3 py-2">
          <span className="text-xs font-medium text-muted-foreground">
            {errorText ? t("toolCard.errorHeading") : t("toolCard.output")}
          </span>
          <ToolResultOutput language={errorText ? "text" : "json"}>
            {outputText}
          </ToolResultOutput>
        </div>
      ) : null}
    </ToolResult>
  );
}

function stringField(record: Record<string, unknown> | null, key: string) {
  const value = record?.[key];
  return typeof value === "string" ? value : undefined;
}

/**
 * Renderer for a tool that produces a document. While the model writes
 * the call, the card shows the title and the last lines of the content
 * as they arrive; once the tool returns a `title` (and optionally a
 * `documentId`, `kind` and `content`) the whole card opens it. A
 * finished call with no title falls back to the generic card, so a tool
 * whose shape drifts renders honestly rather than blank.
 *
 * Opening lands in the canvas when the page has one, and on the
 * document's preview on the `/artifacts` page otherwise.
 */
export function ArtifactLinkCard(props: ToolRendererProps) {
  const {
    toolName,
    state,
    input,
    output,
    errorText,
    messageId,
    isReadonly,
    actions,
  } = props;
  const t = useTranslations("chat");

  const result =
    output && typeof output === "object"
      ? (output as Record<string, unknown>)
      : null;
  const draft =
    input && typeof input === "object"
      ? (input as Record<string, unknown>)
      : null;
  const title = stringField(result, "title") ?? stringField(draft, "title");

  if (state === "output-available" && !title)
    return <DefaultToolCard {...props} />;

  const kind =
    stringField(result, "kind") ??
    stringField(draft, "kind") ??
    resolveToolRenderer(toolName).canvas?.kind ??
    "text";
  const status =
    state === "output-error" || state === "output-denied"
      ? "error"
      : state === "output-available"
        ? "ready"
        : "streaming";
  const documentId =
    stringField(result, "documentId") ?? stringField(result, "id");
  const content = stringField(result, "content");
  const ref: CanvasRef = {
    id: documentId ?? messageId,
    kind,
    title: title ?? "",
    ...(documentId ? { documentId } : {}),
    ...(content !== undefined ? { content } : {}),
    status: "ready",
  };
  const canOpen = status === "ready" && !isReadonly;

  return (
    <ArtifactCard
      title={title || t("artifactCard.untitled")}
      kind={kind}
      status={status}
      error={errorText}
      preview={stringField(draft, "content")}
      onOpen={canOpen && actions ? () => actions.openCanvas(ref) : undefined}
      href={
        canOpen && !actions && documentId
          ? `/artifacts?document=${encodeURIComponent(documentId)}`
          : undefined
      }
    />
  );
}

function recordOf(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object"
    ? (value as Record<string, unknown>)
    : null;
}

/** A unified diff (`@@ -1,3 +1,4 @@` hunks) as the diff view's lines. */
export function parseUnifiedDiff(patch: string): FileDiffLine[] {
  const lines: FileDiffLine[] = [];
  let oldLine = 0;
  let newLine = 0;
  for (const raw of patch.split("\n")) {
    const hunk = raw.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
    if (hunk) {
      oldLine = Number(hunk[1]);
      newLine = Number(hunk[2]);
      continue;
    }
    if (raw.startsWith("+++") || raw.startsWith("---")) continue;
    if (raw.startsWith("diff ") || raw.startsWith("index ")) continue;
    const id = `${lines.length}`;
    if (raw.startsWith("+")) {
      lines.push({
        id,
        type: "added",
        newLine: newLine++,
        content: raw.slice(1),
      });
    } else if (raw.startsWith("-")) {
      lines.push({
        id,
        type: "removed",
        oldLine: oldLine++,
        content: raw.slice(1),
      });
    } else if (raw.startsWith(" ") || (raw === "" && lines.length > 0)) {
      lines.push({
        id,
        type: "context",
        oldLine: oldLine++,
        newLine: newLine++,
        content: raw.slice(1),
      });
    }
  }
  return lines;
}

/**
 * A tool that edits a file, drawn as the diff it applied: added and
 * removed lines stream in while the call runs, then the card settles.
 * It reads `path` (or `file`) and either `lines` (the diff view's own
 * shape) or `diff`/`patch` (a unified diff) from the output, falling
 * back to the input while the call is still running. Anything else
 * falls back to the generic card.
 */
export function FileDiffCard(props: ToolRendererProps) {
  const { state, input, output } = props;
  const t = useTranslations("chat");
  const result = recordOf(output) ?? recordOf(input);
  const file =
    stringField(result, "path") ??
    stringField(result, "file") ??
    stringField(recordOf(input), "path");
  const patch = stringField(result, "diff") ?? stringField(result, "patch");
  const given = result?.lines;
  const lines = Array.isArray(given)
    ? (given as FileDiffLine[])
    : patch
      ? parseUnifiedDiff(patch)
      : null;

  if (!file || !lines || state === "output-error" || state === "output-denied")
    return <DefaultToolCard {...props} />;

  return (
    <FileDiff
      className="max-w-2xl"
      file={file}
      lines={lines}
      status={state === "output-available" ? "complete" : "streaming"}
      copyText={patch}
      statusLabels={{
        streaming: t("fileDiff.applying"),
        complete: t("fileDiff.applied"),
      }}
      copyLabel={t("actions.copy")}
      copiedLabel={t("actions.copied")}
      changesLabel={t("fileDiff.changes")}
    />
  );
}

const IMAGE_STATUS: Record<ToolPartState, ImageGenerationStatus> = {
  "input-streaming": "queued",
  "input-available": "generating",
  "approval-requested": "queued",
  "approval-responded": "generating",
  "output-available": "complete",
  "output-error": "error",
  "output-denied": "error",
};

/**
 * A tool that makes an image: a shimmering frame while it works, the
 * image resolving out of a blur when it lands. It reads `url` (or
 * `imageUrl`, `image`, or the first of `images`) and an optional `alt`
 * from the output, and the `prompt` and `aspectRatio` from the input.
 */
export function ImageGenerationCard(props: ToolRendererProps) {
  const { state, input, output } = props;
  const t = useTranslations("chat");
  const request = recordOf(input);
  const result = recordOf(output);
  const first = Array.isArray(result?.images)
    ? recordOf((result.images as unknown[])[0])
    : null;
  const url =
    stringField(result, "url") ??
    stringField(result, "imageUrl") ??
    stringField(result, "image") ??
    stringField(first, "url");
  const status = IMAGE_STATUS[state];
  const prompt = stringField(request, "prompt");

  if (status === "complete" && !url) return <DefaultToolCard {...props} />;

  return (
    <ImageGeneration
      className="max-w-md"
      status={status}
      prompt={prompt}
      aspectRatio={stringField(request, "aspectRatio")?.replace(":", " / ")}
      statusLabels={{
        queued: t("imageGeneration.queued"),
        generating: t("imageGeneration.generating"),
        refining: t("imageGeneration.refining"),
        complete: t("imageGeneration.complete"),
        error: t("imageGeneration.error"),
      }}
    >
      {url ? (
        <img
          src={url}
          alt={stringField(result, "alt") ?? prompt ?? ""}
          className="size-full object-cover"
        />
      ) : null}
    </ImageGeneration>
  );
}

"use client";

/**
 * Canvas kinds — how a document opened beside the chat is shown and
 * edited, by `kind`. Consumer-owned, a plain object literal.
 *
 * A kind is the content component plus, optionally, its glyph and name
 * (on the transcript's card and the panel's header), a rendered
 * `preview` beside the source for content that has one, the extension
 * a download gets, actions in the panel's header (run, publish) and
 * toolbar items that send a message about the document ("Polish the
 * wording"). The framework ships `text` (ProseMirror over markdown),
 * `code` (CodeMirror, with a live preview for HTML and SVG), `sheet`
 * (a CSV grid) and `image`; a product adds its own — a `report` kind
 * that renders its JSON as a designed page, a `diagram` kind on a graph
 * library — by adding an entry here:
 *
 *   import { ReportCanvas } from "@/components/reports/report-canvas";
 *
 *   export const CANVAS_KINDS: Record<string, CanvasKind> = {
 *     ...DEFAULT_CANVAS_KINDS,
 *     report: { content: ReportCanvas, icon: ChartIcon, labelKey: "reports.kind" },
 *   };
 *
 * The editors load lazily: a document that is still streaming, or one
 * the reader may not edit, renders on the light viewers below and
 * never pulls the editor bundle. The chat's `saveArtifact` tool and
 * `createArtifactWriter` name a kind; the canvas looks it up here and
 * falls back to `text` for one it does not know, so nothing renders
 * blank.
 */

import { Suspense, lazy, type ComponentType, type ReactNode } from "react";
import { type LucideIcon } from "lucide-react";

import {
  CodeView,
  HtmlPreview,
  ImageView,
  SheetView,
  TextView,
  documentKindIcon,
  extensionOf,
  fileNameOf as fileNameFor,
  isPreviewableTitle,
  languageOf,
} from "@/components/ui/document-viewer";
import { Spinner } from "@/components/ui/spinner";

export interface CanvasContentProps {
  content: string;
  /** Streaming in, or settled. */
  status: "streaming" | "ready" | "error";
  /** The document title, for a kind that shows it. */
  title: string;
  /** Read-only: the shared page, an older version, a stream in progress. */
  isReadonly: boolean;
  /** The reader edited the document; the canvas keeps the draft until saved. */
  onChange?: (content: string) => void;
}

export interface CanvasActionContext {
  content: string;
  title: string;
  documentId?: string;
}

export interface CanvasAction {
  /** Accessible name and tooltip — a message key, resolved by the canvas. */
  labelKey: string;
  icon: LucideIcon;
  onClick: (context: CanvasActionContext) => void | Promise<void>;
}

export interface CanvasToolbarItem {
  /** A message key for the button's text. */
  labelKey: string;
  /** The message sent to the chat when clicked. */
  message: string;
}

export interface CanvasKind {
  content: ComponentType<CanvasContentProps>;
  /** The kind's glyph on its card and in the panel's header. */
  icon?: LucideIcon;
  /** A message key naming the kind — "Document", "Code". */
  labelKey?: string;
  /**
   * A rendered view of the document, offered beside its source when
   * `previewable` says this document has one.
   */
  preview?: ComponentType<CanvasContentProps>;
  previewable?: (title: string) => boolean;
  /** The extension a download gets when the title has none. */
  extension?: string;
  actions?: CanvasAction[];
  toolbar?: CanvasToolbarItem[];
}

const TextEditor = lazy(() => import("@/components/chat/canvas/text-editor"));
const CodeEditor = lazy(() => import("@/components/chat/canvas/code-editor"));
const SheetEditor = lazy(() => import("@/components/chat/canvas/sheet-editor"));

function Loading() {
  return (
    <div className="flex h-24 items-center justify-center text-muted-foreground">
      <Spinner />
    </div>
  );
}

/**
 * The viewers below are the shared ones
 * (`@/components/ui/document-viewer`), so a document reads the same
 * here as it does in the artifacts library. What stays here is the
 * editing: which kinds have an editor, and when it is allowed to load.
 */

/** Editable once settled; a rendered view while it streams or is read-only. */
function TextCanvas(props: CanvasContentProps) {
  if (props.isReadonly || props.status === "streaming" || !props.onChange) {
    return (
      <TextView
        content={props.content}
        title={props.title}
        streaming={props.status === "streaming"}
      />
    );
  }
  return (
    <Suspense fallback={<Loading />}>
      <TextEditor {...props} />
    </Suspense>
  );
}

function CodeCanvas(props: CanvasContentProps) {
  if (props.isReadonly || props.status === "streaming" || !props.onChange) {
    return <CodeView content={props.content} title={props.title} />;
  }
  return (
    <Suspense fallback={<Loading />}>
      <CodeEditor {...props} />
    </Suspense>
  );
}

function CodePreview({ content, title }: CanvasContentProps) {
  return <HtmlPreview content={content} title={title} />;
}

function SheetCanvas(props: CanvasContentProps) {
  if (props.status === "streaming") {
    return <SheetView content={props.content} title={props.title} />;
  }
  return (
    <Suspense fallback={<Loading />}>
      <SheetEditor {...props} />
    </Suspense>
  );
}

/** A generated image: the content is a data URL or an https URL. */
function ImageCanvas({ content, title }: CanvasContentProps): ReactNode {
  if (!content) return null;
  return <ImageView content={content} title={title} />;
}

/**
 * Re-exported, not redefined: the canvas and the transcript's artifact
 * card ask this module for them, and a kind config is where a reader
 * looks for "how is this document named and highlighted".
 */
export { extensionOf, languageOf };

/** The name a downloaded document gets: its title, with an extension. */
export function fileNameOf(title: string, kind: CanvasKind): string {
  return fileNameFor(title, kind.extension);
}

export const DEFAULT_CANVAS_KINDS: Record<string, CanvasKind> = {
  text: {
    content: TextCanvas,
    icon: documentKindIcon("text"),
    labelKey: "chat.canvas.kinds.text",
    extension: "md",
  },
  code: {
    content: CodeCanvas,
    icon: documentKindIcon("code"),
    labelKey: "chat.canvas.kinds.code",
    preview: CodePreview,
    previewable: isPreviewableTitle,
    extension: "txt",
  },
  sheet: {
    content: SheetCanvas,
    icon: documentKindIcon("sheet"),
    labelKey: "chat.canvas.kinds.sheet",
    extension: "csv",
  },
  image: {
    content: ImageCanvas,
    icon: documentKindIcon("image"),
    labelKey: "chat.canvas.kinds.image",
    extension: "png",
  },
};

export const CANVAS_KINDS: Record<string, CanvasKind> = {
  ...DEFAULT_CANVAS_KINDS,
};

export function resolveCanvasKind(kind: string): CanvasKind {
  return CANVAS_KINDS[kind] ?? CANVAS_KINDS.text ?? DEFAULT_CANVAS_KINDS.text!;
}

/**
 * How one message's parts are laid out, as plain data — no React, so
 * the rules are pinned by tests.
 *
 * `groupParts` folds a run of the agent's own work — reasoning and the
 * tool calls between its words — into one activity segment, the way a
 * reader follows it: "Searched the web ▸", then the answer. A tool
 * that draws its own card (a document, a gated call awaiting the
 * reader) breaks the run and stands on its own. `step-start` and empty
 * text are boundaries the SDK keeps; they never break a run.
 *
 * `collectSources` gathers what the answer leans on — the AI SDK's
 * `source-url`/`source-document` parts and the sources a tool returned
 * — numbered the way `[n]` markers in the text refer to them.
 */

export type PartLike = { type: string };

export type PartAt<P> = { index: number; part: P };

export type MessageSegment<P> =
  | { kind: "part"; index: number; part: P }
  | { kind: "activity"; key: string; parts: PartAt<P>[] };

const SETTLED_TOOL_STATES = new Set([
  "output-available",
  "output-error",
  "output-denied",
]);

export function isToolPart(part: PartLike): boolean {
  return part.type.startsWith("tool-") || part.type === "dynamic-tool";
}

export function isReasoningPart(part: PartLike): boolean {
  return part.type === "reasoning";
}

function isBoundary(part: PartLike): boolean {
  if (part.type === "step-start") return true;
  return part.type === "text" && !(part as { text?: string }).text;
}

/**
 * Ordered segments. `isCard(part)` says a tool part draws its own card
 * instead of a row in the activity stream.
 */
export function groupParts<P extends PartLike>(
  parts: readonly P[],
  isCard: (part: P) => boolean
): MessageSegment<P>[] {
  const segments: MessageSegment<P>[] = [];
  let run: PartAt<P>[] | null = null;

  parts.forEach((part, index) => {
    if (isBoundary(part)) return;
    const joins =
      (isReasoningPart(part) && Boolean((part as { text?: string }).text)) ||
      (isToolPart(part) && !isCard(part));
    if (joins) {
      if (!run) {
        run = [];
        segments.push({
          kind: "activity",
          key: `activity-${index}`,
          parts: run,
        });
      }
      run.push({ index, part });
      return;
    }
    if (isReasoningPart(part)) return;
    run = null;
    segments.push({ kind: "part", index, part });
  });

  return segments;
}

/**
 * An activity segment is working while its message streams and it is
 * either the newest thing in the message or still waiting on a call.
 */
export function isActivityWorking<P extends PartLike>(
  segment: Extract<MessageSegment<P>, { kind: "activity" }>,
  isLastSegment: boolean,
  isStreaming: boolean
): boolean {
  if (!isStreaming) return false;
  if (isLastSegment) return true;
  return segment.parts.some(
    ({ part }) =>
      isToolPart(part) &&
      !SETTLED_TOOL_STATES.has((part as { state?: string }).state ?? "")
  );
}

export function isSettledToolState(state: string | undefined): boolean {
  return SETTLED_TOOL_STATES.has(state ?? "");
}

export type SourceItem = {
  url?: string;
  title?: string;
  /** Where the source lives, when the url does not say (a redirect). */
  domain?: string;
  snippet?: string;
  /** The `[n]` the model was told to cite this by, when the tool numbered it. */
  index?: number;
};

export type NumberedSource = SourceItem & { id: string; index: number };

/**
 * The sources a tool output carries by convention: `{ sources: [{ url,
 * title?, domain?, snippet?, index? }] }`. Anything else yields none.
 */
export function sourcesFromToolOutput(output: unknown): SourceItem[] {
  if (!output || typeof output !== "object") return [];
  const raw = (output as { sources?: unknown }).sources;
  if (!Array.isArray(raw)) return [];
  return raw.flatMap((entry): SourceItem[] => {
    if (!entry || typeof entry !== "object") return [];
    const record = entry as Record<string, unknown>;
    const url = typeof record.url === "string" ? record.url : undefined;
    const title = typeof record.title === "string" ? record.title : undefined;
    if (!url && !title) return [];
    return [
      {
        ...(url ? { url } : {}),
        ...(title ? { title } : {}),
        ...(typeof record.domain === "string" ? { domain: record.domain } : {}),
        ...(typeof record.snippet === "string"
          ? { snippet: record.snippet }
          : {}),
        ...(typeof record.index === "number" && Number.isInteger(record.index)
          ? { index: record.index }
          : {}),
      },
    ];
  });
}

/**
 * Numbered sources for one message. A source the tool numbered keeps
 * its number (the model cites by it); the rest take the next free one
 * in part order. A url already numbered is not listed twice.
 */
export function collectSources<P extends PartLike>(
  parts: readonly P[],
  sourcesOf: (part: P) => SourceItem[]
): NumberedSource[] {
  const byIndex = new Map<number, NumberedSource>();
  const seenUrls = new Set<string>();
  const unnumbered: SourceItem[] = [];

  for (const part of parts) {
    for (const source of sourcesOf(part)) {
      if (source.index !== undefined && source.index >= 1) {
        if (byIndex.has(source.index)) continue;
        byIndex.set(source.index, {
          ...source,
          id: String(source.index),
          index: source.index,
        });
        if (source.url) seenUrls.add(source.url);
      } else {
        unnumbered.push(source);
      }
    }
  }

  let next = 1;
  for (const source of unnumbered) {
    if (source.url) {
      if (seenUrls.has(source.url)) continue;
      seenUrls.add(source.url);
    }
    while (byIndex.has(next)) next += 1;
    byIndex.set(next, { ...source, id: String(next), index: next });
  }

  return [...byIndex.values()].sort((a, b) => a.index - b.index);
}

/** The AI SDK's own source parts, as source items. */
export function sourcesFromSourcePart(part: PartLike): SourceItem[] {
  if (part.type !== "source-url" && part.type !== "source-document") return [];
  const source = part as { url?: string; title?: string; filename?: string };
  const title = source.title ?? source.filename;
  if (!source.url && !title) return [];
  return [
    {
      ...(source.url ? { url: source.url } : {}),
      ...(title ? { title } : {}),
    },
  ];
}

/** The host a source lives on, without `www.`. */
export function hostnameOf(url: string | undefined): string | undefined {
  if (!url) return undefined;
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return undefined;
  }
}

/** A source's display domain: what it says, else its url's host. */
export function sourceDomain(source: SourceItem): string | undefined {
  return source.domain ?? hostnameOf(source.url);
}

const CITE_PREFIX = "#cite-";

/**
 * `[3]`, `[3][4]` and `[3, 4]` in the text become one link each run —
 * `[3](#cite-3)`, `[3,4](#cite-3,4)` — which the markdown anchor
 * override renders as a citation pill. Only numbers the message has a
 * source for; a markdown link (`[3](…)`) is left alone.
 */
export function linkCitations(
  text: string,
  known: ReadonlySet<number>
): string {
  if (known.size === 0) return text;
  return text.replace(/(?:\[\d{1,3}(?:\s*,\s*\d{1,3})*\])+(?!\()/g, (run) => {
    const numbers = [...run.matchAll(/\d{1,3}/g)]
      .map((match) => Number(match[0]))
      .filter((n) => known.has(n));
    if (numbers.length === 0) return run;
    const unique = [...new Set(numbers)];
    return `[${unique.join(",")}](${CITE_PREFIX}${unique.join(",")})`;
  });
}

/**
 * A readable name for a page that came with none — search grounding
 * often gives only the domain: the last meaningful path segment,
 * de-slugged. `…/blog-posts/node-js-end-of-life-dates` → "Node js end
 * of life dates". Undefined for a site's front page.
 */
export function titleFromUrl(url: string | undefined): string | undefined {
  if (!url) return undefined;
  let segments: string[];
  try {
    segments = new URL(url).pathname.split("/").filter(Boolean);
  } catch {
    return undefined;
  }
  for (const segment of segments.reverse()) {
    const words = decodeURIComponent(segment)
      .replace(/\.(html?|php|aspx?)$/i, "")
      .replace(/[-_+]+/g, " ")
      .trim();
    // Ids, hashes and dates name nothing a reader recognises.
    if (
      words.length < 4 ||
      !/[a-z]{3}/i.test(words) ||
      /^[\d\s]+$/.test(words)
    ) {
      continue;
    }
    return words.charAt(0).toUpperCase() + words.slice(1);
  }
  return undefined;
}

/** The source numbers a citation link points at, or null for any other link. */
export function parseCitationHref(href: string | undefined): number[] | null {
  if (!href?.startsWith(CITE_PREFIX)) return null;
  const numbers = href
    .slice(CITE_PREFIX.length)
    .split(",")
    .map(Number)
    .filter((n) => Number.isInteger(n) && n >= 1);
  return numbers.length > 0 ? numbers : null;
}

/** The first string in a tool's input — the query, the path, the name. */
export function primaryInput(input: unknown): string | undefined {
  if (typeof input === "string") return input || undefined;
  if (!input || typeof input !== "object") return undefined;
  for (const value of Object.values(input as Record<string, unknown>)) {
    if (typeof value === "string" && value.trim()) return value;
  }
  return undefined;
}

/**
 * Chat composition config — the consumer-owned extension point for
 * everything a product adds to the chat surface without editing an
 * installed component.
 *
 * Every seam is optional — a fresh install ships this file with an
 * empty `chatConfig`, so the chat surface renders its baseline UI:
 *
 *  - `agent`: the identity shown in the conversation header — a
 *    name and optional icon/emoji. Omit it (the default) and the
 *    header falls back to this item's own translated "Assistant"
 *    label (`messages/en/chat.json`'s `agent.defaultName`). `name`
 *    and `icon` are plain strings rather than message keys because
 *    an agent's display name is product copy, not framework copy.
 *  - `starters`: conversation-starter prompts shown on an empty
 *    conversation, as *message keys* — not literal strings — resolved
 *    against your app's full message tree via next-intl's
 *    namespace-less `useTranslations()`. E.g. `"support.starters.refund"`
 *    resolves `t("support.starters.refund")` from your own
 *    `messages/<locale>/support.json`. Keeping this to keys is what
 *    keeps starters translatable without editing `chat-thread.tsx`.
 *  - `headerRight`: a component the header renders on its right side,
 *    next to the History/New/Delete controls — a progress indicator,
 *    an export button reading product state for `conversationId`.
 *  - `attachments`: what the composer lets the reader attach. Unset,
 *    the "+" control is hidden. Mirror the server's policy in
 *    `lib/chat-server-config.ts` (`attachments.accept`, `maxBytes`,
 *    `mode`): the composer keeps the reader from picking a file the
 *    route would refuse, and in `stored` mode uploads it first.
 *  - `activity`: how reasoning, tool calls and runtime steps read in
 *    the transcript — `inline` (each as its own card, the default) or
 *    `timeline` (grouped into one collapsible activity block per
 *    reply, the way an agent's work is usually shown).
 *  - `commands`: slash commands the composer offers when a message
 *    starts with `/`. Each names a message key for its label and either
 *    inserts text or runs a callback.
 *  - `mentions`: an `@` picker — files, pages, knowledge bases — with a
 *    search you bind; the pick lands in the message as `@label` and in
 *    the turn's `body.mentions` for `resolveAgent`.
 *  - `sendAutomaticallyWhen`: an auto-continuation predicate, passed to
 *    `useChat`. Default: continue after tool results and after approval
 *    answers, which is what a tool loop and a gated tool need.
 *
 * Edit this file directly to point at your product's own components —
 * this is consumer-owned source, not a package import:
 *
 *   import { ExportReportButton } from "@/components/support/export-report-button";
 *
 *   export const chatConfig: ChatConfig = {
 *     agent: { id: "support-assistant", name: "Support Assistant", icon: "🎧" },
 *     starters: ["support.starters.refund", "support.starters.shipping"],
 *     headerRight: ExportReportButton,
 *     attachments: { accept: ["image/png", "image/jpeg", "application/pdf"], maxBytes: 5_000_000 },
 *   };
 */

import type { ComponentType } from "react";
import type { UIMessage } from "ai";

/** Props passed to a consumer-bound `headerRight` component. */
export interface ChatHeaderRightProps {
  conversationId: string;
}

export interface ChatAgentIdentity {
  /** Stable id for the agent this chat surface represents. */
  id?: string;
  /** Display name. Falls back to this item's translated default when omitted. */
  name?: string;
  /** A short icon or emoji shown beside the name. */
  icon?: string;
}

export interface ChatAttachmentsConfig {
  /** Media types the composer accepts, e.g. `["image/png", "application/pdf"]`. */
  accept: string[];
  maxFiles?: number;
  /** In bytes. */
  maxBytes?: number;
  /**
   * `inline` (default): files travel in the message as data URLs.
   * `stored`: files upload to `/api/chat/upload` first and the message
   * carries their app URL — bind a storage adapter and mount the two
   * routes (see `@intelligo-dev/chat`'s `createChatUploadHandler`).
   */
  mode?: "inline" | "stored";
  /** Where the composer uploads in `stored` mode. Default `/api/chat/upload`. */
  uploadUrl?: string;
}

export interface ChatCommand {
  /** Typed after `/`, e.g. `"summarize"`. */
  id: string;
  /** Message key for the label shown in the picker. */
  labelKey: string;
  /** Message key for a one-line description. */
  descriptionKey?: string;
  /** Text to put in the composer in place of `/id`. */
  insert?: string;
  /** Or run something — send a message, open a dialog. */
  run?: (context: {
    conversationId: string;
    setText: (text: string) => void;
    send: (text: string) => void;
  }) => void;
}

export interface ChatMention {
  id: string;
  label: string;
  description?: string;
  /** Grouped in the picker under this heading (a message key). */
  groupKey?: string;
}

export interface ChatMentionsConfig {
  /** Default `@`. */
  trigger?: string;
  search: (query: string) => Promise<ChatMention[]> | ChatMention[];
}

export interface ChatConfig {
  /** Identity shown in the conversation header. Omit for the default "Assistant" label. */
  agent?: ChatAgentIdentity;
  /** Conversation-starter message keys — see the module doc comment above. */
  starters?: string[];
  /** Rendered on the right side of the conversation header. */
  headerRight?: ComponentType<ChatHeaderRightProps>;
  /** What the composer lets the reader attach. Unset: no attachments. */
  attachments?: ChatAttachmentsConfig;
  /** How reasoning, tool calls and runtime steps read. Default `inline`. */
  activity?: "inline" | "timeline";
  /** Slash commands the composer offers. */
  commands?: ChatCommand[];
  /** The `@` picker. */
  mentions?: ChatMentionsConfig;
  /**
   * Auto-continuation predicate, passed straight to `useChat`'s
   * `sendAutomaticallyWhen`. Default: continue when the reader answered
   * an approval, or when a card supplied a client-side tool's result.
   * A turn that ends on a server-run tool (a card waiting for a click)
   * is not re-sent.
   */
  sendAutomaticallyWhen?: (options: {
    messages: UIMessage[];
  }) => boolean | PromiseLike<boolean>;
}

/**
 * Default chat configuration — a fresh install has no product identity,
 * starters, attachments or commands to add.
 */
export const chatConfig: ChatConfig = {};

import "server-only";

/**
 * What the chat page knows about the caller's credit before they type.
 *
 * The transport already refuses a turn it cannot fund — admission runs
 * inside `executions.begin()` and answers 402. That is the correct
 * enforcement point and the wrong place to *tell someone*: by then they
 * have written a message and watched it fail. This is the read that
 * lets the page say so first — an estimate, never a reservation, priced
 * against the model a turn would run on.
 */

import { getChatQuotaState as readChatQuotaState } from "@intelligo-dev/chat";
import type { ChatQuotaState } from "@intelligo-dev/chat/client";

import { CHAT_MODEL_ID } from "@/lib/chat-model";

export type { ChatQuotaState };

/** Never throws: a quota read that fails costs the reader a banner, not the conversation. */
export function getChatQuotaState(): Promise<ChatQuotaState | null> {
  return readChatQuotaState({
    modelId: CHAT_MODEL_ID,
    upgradeHref: "/pricing",
  });
}

"use client";

/**
 * Versions of a reply, kept where the reader can flip between them.
 *
 * Regenerating a reply or editing a message does not lose the earlier
 * attempt: the tail of the conversation from that point on is kept as
 * a version, and the message that starts the tail shows a `< 2 / 3 >`
 * pager. Versions live in this tab (mirrored to `sessionStorage`, so a
 * refresh within the tab keeps them); the server persists the latest
 * path only. That is a deliberate scope: the row stays a list, no
 * migration, and a reload shows what was last said.
 *
 * An *anchor* is the message just before the point that branched — the
 * user message a reply answers, or the message before an edited user
 * message. `ROOT` anchors a branch at the very start.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { UIMessage } from "ai";

export const ROOT_ANCHOR = "__root__";

type VersionSet = {
  tails: UIMessage[][];
  active: number;
};

export type ChatVersion = { index: number; count: number };

type Pending = { anchorId: string };

function storageKey(conversationId: string) {
  return `chat:versions:${conversationId}`;
}

function readStored(conversationId: string): Record<string, VersionSet> {
  try {
    const raw = sessionStorage.getItem(storageKey(conversationId));
    return raw ? (JSON.parse(raw) as Record<string, VersionSet>) : {};
  } catch {
    return {};
  }
}

function writeStored(
  conversationId: string,
  versions: Record<string, VersionSet>
) {
  try {
    if (Object.keys(versions).length === 0) {
      sessionStorage.removeItem(storageKey(conversationId));
    } else {
      sessionStorage.setItem(
        storageKey(conversationId),
        JSON.stringify(versions)
      );
    }
  } catch {
    // Storage is a convenience; a private window without it still chats.
  }
}

function anchorIndex(messages: UIMessage[], anchorId: string): number {
  if (anchorId === ROOT_ANCHOR) return -1;
  return messages.findIndex((message) => message.id === anchorId);
}

export function useChatVersions({
  conversationId,
  messages,
  setMessages,
  status,
}: {
  conversationId: string;
  messages: UIMessage[];
  setMessages: (messages: UIMessage[]) => void;
  status: "submitted" | "streaming" | "ready" | "error";
}) {
  const [versions, setVersions] = useState<Record<string, VersionSet>>({});
  const pending = useRef<Pending | null>(null);
  const hydrated = useRef(false);

  useEffect(() => {
    setVersions(readStored(conversationId));
    hydrated.current = true;
  }, [conversationId]);

  useEffect(() => {
    if (hydrated.current) writeStored(conversationId, versions);
  }, [conversationId, versions]);

  /** Keep the tail on screen before it is replaced. */
  const snapshot = useCallback(
    (anchorId: string) => {
      const at = anchorIndex(messages, anchorId);
      const tail = messages.slice(at + 1);
      setVersions((previous) => {
        const existing = previous[anchorId];
        if (existing) {
          const tails = [...existing.tails];
          tails[existing.active] = tail;
          return { ...previous, [anchorId]: { ...existing, tails } };
        }
        return { ...previous, [anchorId]: { tails: [tail], active: 0 } };
      });
      pending.current = { anchorId };
    },
    [messages]
  );

  /** Before `regenerate({ messageId })`: the message before the reply anchors it. */
  const beforeRegenerate = useCallback(
    (assistantMessageId: string) => {
      const at = messages.findIndex((m) => m.id === assistantMessageId);
      if (at === -1) return;
      snapshot(at === 0 ? ROOT_ANCHOR : messages[at - 1]!.id);
    },
    [messages, snapshot]
  );

  /** Before an edit re-sends a user message with a new id. */
  const beforeEdit = useCallback(
    (userMessageId: string) => {
      const at = messages.findIndex((m) => m.id === userMessageId);
      if (at === -1) return;
      snapshot(at === 0 ? ROOT_ANCHOR : messages[at - 1]!.id);
    },
    [messages, snapshot]
  );

  // When the turn that followed a snapshot settles, the tail on screen
  // becomes the newest version. While idle, the active version tracks
  // whatever the thread now holds after its anchor, so a follow-up sent
  // on an older version grows that version rather than being lost.
  useEffect(() => {
    if (status !== "ready") return;
    const commit = pending.current;
    pending.current = null;
    setVersions((previous) => {
      let next = previous;
      let changed = false;
      for (const [anchorId, set] of Object.entries(previous)) {
        const at = anchorIndex(messages, anchorId);
        if (at === -1 && anchorId !== ROOT_ANCHOR) continue;
        const tail = messages.slice(at + 1);
        if (commit?.anchorId === anchorId) {
          next = {
            ...next,
            [anchorId]: {
              tails: [...set.tails, tail],
              active: set.tails.length,
            },
          };
          changed = true;
        } else if (tail.length > 0) {
          const tails = [...set.tails];
          tails[set.active] = tail;
          next = { ...next, [anchorId]: { ...set, tails } };
          changed = true;
        }
      }
      return changed ? next : previous;
    });
  }, [status, messages]);

  const select = useCallback(
    (anchorId: string, index: number) => {
      const set = versions[anchorId];
      const tail = set?.tails[index];
      if (!set || !tail) return;
      const at = anchorIndex(messages, anchorId);
      if (at === -1 && anchorId !== ROOT_ANCHOR) return;
      setVersions((previous) => ({
        ...previous,
        [anchorId]: { ...set, active: index },
      }));
      setMessages([...messages.slice(0, at + 1), ...tail]);
    },
    [versions, messages, setMessages]
  );

  /** The pager state for the message that follows `anchorId`, if it has versions. */
  const versionOf = useMemo(() => {
    const byFirstMessage = new Map<
      string,
      ChatVersion & { anchorId: string }
    >();
    for (const [anchorId, set] of Object.entries(versions)) {
      if (set.tails.length < 2) continue;
      const at = anchorIndex(messages, anchorId);
      if (at === -1 && anchorId !== ROOT_ANCHOR) continue;
      const first = messages[at + 1];
      if (!first) continue;
      byFirstMessage.set(first.id, {
        anchorId,
        index: set.active,
        count: set.tails.length,
      });
    }
    return (messageId: string) => byFirstMessage.get(messageId) ?? null;
  }, [versions, messages]);

  return { beforeRegenerate, beforeEdit, select, versionOf };
}

"use client";

/**
 * The composer's unsent text, kept per conversation.
 *
 * Switching models, opening another conversation and coming back, or a
 * tab that reloads should never cost a half-written message. The draft
 * lives in `localStorage` under the conversation id and is cleared
 * the moment it is sent.
 */

import { useCallback, useEffect, useRef, useState } from "react";

const DEBOUNCE_MS = 300;

function key(conversationId: string) {
  return `chat:draft:${conversationId}`;
}

export function useChatDraft(conversationId: string) {
  const [value, setValue] = useState("");
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    try {
      setValue(localStorage.getItem(key(conversationId)) ?? "");
    } catch {
      setValue("");
    }
  }, [conversationId]);

  const update = useCallback(
    (next: string) => {
      setValue(next);
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => {
        try {
          if (next) localStorage.setItem(key(conversationId), next);
          else localStorage.removeItem(key(conversationId));
        } catch {
          // A draft is a convenience, not a record.
        }
      }, DEBOUNCE_MS);
    },
    [conversationId]
  );

  const clear = useCallback(() => {
    if (timer.current) clearTimeout(timer.current);
    setValue("");
    try {
      localStorage.removeItem(key(conversationId));
    } catch {
      // See above.
    }
  }, [conversationId]);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    []
  );

  return { value, setValue: update, clear };
}

"use client";

/**
 * The keyboard a chat is expected to have.
 *
 *   ⌘/Ctrl+K   new chat
 *   Esc        stop a reply that is streaming
 *
 * Enter / Shift+Enter live in the composer, and
 * ArrowUp-to-edit-the-last-message is the composer's too, because it
 * only means that when the composer is empty and focused.
 *
 * Window-level, but polite: a shortcut never fires while the reader is
 * typing in some other field, except Esc, which is always "stop".
 */

import { useEffect } from "react";

export function useChatShortcuts({
  onNewChat,
  onStop,
  isStreaming,
}: {
  onNewChat: () => void;
  onStop: () => void;
  isStreaming: boolean;
}) {
  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.defaultPrevented) return;
      const modifier = event.metaKey || event.ctrlKey;

      if (modifier && (event.key === "k" || event.key === "K")) {
        event.preventDefault();
        onNewChat();
        return;
      }
      if (event.key === "Escape" && isStreaming) {
        event.preventDefault();
        onStop();
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [onNewChat, onStop, isStreaming]);
}

"use client";

/**
 * `/` commands and `@` mentions in the composer.
 *
 * Watches the text at the caret: a `/` that starts the message opens
 * the command list, an `@` that starts a word opens the mention picker,
 * and what follows the trigger filters both. Picking a command inserts
 * its text or runs it; picking a mention writes `@label` and keeps the
 * pick, so the turn can carry `body.mentions` for `resolveAgent`.
 *
 * Both lists come from `lib/chat-config.tsx`; a deployment with
 * neither never sees a menu.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useTranslations } from "next-intl";

import type { ComposerMenuOption } from "@/components/ui/ai-composer-menu";
import { chatConfig, type ChatMention } from "@/lib/chat-config";

export type ComposerMenuKind = "command" | "mention";

type Trigger = { kind: ComposerMenuKind; start: number; query: string };

const SEARCH_DEBOUNCE_MS = 150;

/** The trigger under the caret, if the text at that point is one. */
export function detectTrigger(
  text: string,
  caret: number,
  mentionTrigger = "@"
): Trigger | null {
  const before = text.slice(0, caret);
  if (/\s/.test(before.slice(-1))) return null;

  const slash = before.match(/^\/([\w-]*)$/);
  if (slash) return { kind: "command", start: 0, query: slash[1] ?? "" };

  const at = before.lastIndexOf(mentionTrigger);
  if (at === -1) return null;
  if (at > 0 && !/\s/.test(before[at - 1]!)) return null;
  const query = before.slice(at + mentionTrigger.length);
  if (/\s/.test(query)) return null;
  return { kind: "mention", start: at, query };
}

export function useComposerMenu({
  value,
  setValue,
  conversationId,
  send,
  textareaRef,
}: {
  value: string;
  setValue: (text: string) => void;
  conversationId: string;
  send: (text: string) => void;
  textareaRef: React.RefObject<HTMLTextAreaElement | null>;
}) {
  const tAny = useTranslations();
  const [trigger, setTrigger] = useState<Trigger | null>(null);
  const [mentionResults, setMentionResults] = useState<ChatMention[]>([]);
  const [picked, setPicked] = useState<ChatMention[]>([]);
  const dismissed = useRef<string | null>(null);
  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const commands = chatConfig.commands ?? [];
  const mentions = chatConfig.mentions;
  const mentionTrigger = mentions?.trigger ?? "@";

  /** Re-read the caret after every change; the trigger follows it. */
  const refresh = useCallback(() => {
    const element = textareaRef.current;
    if (!element) return;
    const caret = element.selectionStart ?? element.value.length;
    const next = detectTrigger(element.value, caret, mentionTrigger);
    if (next?.kind === "command" && commands.length === 0) {
      setTrigger(null);
      return;
    }
    if (next?.kind === "mention" && !mentions) {
      setTrigger(null);
      return;
    }
    const key = next ? `${next.kind}:${next.start}` : null;
    if (key && dismissed.current === key) {
      setTrigger(null);
      return;
    }
    if (!next) dismissed.current = null;
    setTrigger(next);
  }, [textareaRef, mentionTrigger, commands.length, mentions]);

  useEffect(() => {
    refresh();
  }, [value, refresh]);

  useEffect(() => {
    if (trigger?.kind !== "mention" || !mentions) return;
    if (searchTimer.current) clearTimeout(searchTimer.current);
    const query = trigger.query;
    searchTimer.current = setTimeout(() => {
      void Promise.resolve(mentions.search(query)).then(setMentionResults);
    }, SEARCH_DEBOUNCE_MS);
    return () => {
      if (searchTimer.current) clearTimeout(searchTimer.current);
    };
  }, [trigger?.kind, trigger?.query, mentions]);

  const options = useMemo<ComposerMenuOption[]>(() => {
    if (trigger?.kind === "command") {
      return commands.map((command) => ({
        value: command.id,
        label: tAny(command.labelKey),
        description: command.descriptionKey
          ? tAny(command.descriptionKey)
          : `/${command.id}`,
      }));
    }
    if (trigger?.kind === "mention") {
      return mentionResults.map((mention) => ({
        value: mention.id,
        label: mention.label,
        description: mention.description,
        group: mention.groupKey ? tAny(mention.groupKey) : undefined,
      }));
    }
    return [];
  }, [trigger?.kind, commands, mentionResults, tAny]);

  const close = useCallback(() => {
    if (trigger) dismissed.current = `${trigger.kind}:${trigger.start}`;
    setTrigger(null);
  }, [trigger]);

  const select = useCallback(
    (option: ComposerMenuOption) => {
      if (!trigger) return;
      const element = textareaRef.current;
      const caret = element?.selectionStart ?? value.length;
      const after = value.slice(caret);

      if (trigger.kind === "command") {
        const command = commands.find((c) => c.id === option.value);
        setTrigger(null);
        if (!command) return;
        if (command.run) {
          setValue("");
          command.run({ conversationId, setText: setValue, send });
          return;
        }
        setValue(`${command.insert ?? ""}${after}`);
        return;
      }

      const mention = mentionResults.find((m) => m.id === option.value);
      setTrigger(null);
      if (!mention) return;
      setPicked((previous) =>
        previous.some((m) => m.id === mention.id)
          ? previous
          : [...previous, mention]
      );
      const before = value.slice(0, trigger.start);
      setValue(`${before}${mentionTrigger}${mention.label} ${after}`);
    },
    [
      trigger,
      textareaRef,
      value,
      commands,
      setValue,
      conversationId,
      send,
      mentionResults,
      mentionTrigger,
    ]
  );

  /** The mentions still present in the text, for the turn's body. */
  const activeMentions = useMemo(
    () =>
      picked.filter((mention) =>
        value.includes(`${mentionTrigger}${mention.label}`)
      ),
    [picked, value, mentionTrigger]
  );

  const clearPicked = useCallback(() => setPicked([]), []);

  return {
    open:
      trigger !== null && (options.length > 0 || trigger.kind === "mention"),
    kind: trigger?.kind ?? null,
    query: trigger?.query ?? "",
    options,
    select,
    close,
    refresh,
    mentions: activeMentions,
    clearPicked,
  };
}

"use client";

/**
 * The page's chat shell: the thread on the left, the canvas on the
 * right when a document is open. Owns the canvas state — which
 * document, its streamed content so far — so the thread and every
 * card can open, feed and close the same panel, and a card can show
 * the lines being written (`ArtifactStreamProvider`).
 *
 * From `md` up the two sit side by side: the reader drags the edge (or
 * uses the arrow keys on it) to resize the canvas, or expands it to
 * fill the page. Below, the canvas is a sheet over the thread. The
 * thread keeps one place in the tree either way: a layout that moved
 * or remounted it would drop the conversation in flight (a resizable
 * panel group did exactly that when its panel count changed), so the
 * edge is a plain handle on the canvas's width and an expanded canvas
 * hides the thread rather than replacing it.
 */

import {
  useCallback,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import { useTranslations } from "next-intl";
import type { UIMessage } from "ai";

import type {
  ChatArtifactData,
  ChatModelOption,
} from "@intelligo-dev/chat/client";

import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { useIsMobile } from "@/hooks/use-mobile";
import type { CanvasRef } from "@/lib/chat-renderers";
import { cn } from "@/lib/utils";

import { ArtifactStreamProvider } from "./artifact-card";
import { ChatCanvas, type CanvasState } from "./chat-canvas";
import { ChatThread } from "./chat-thread";
import type { ChatQuotaState } from "./credit-status-banner";
import type { MessageVote } from "./message-actions";

interface ChatWorkspaceProps {
  conversationId: string;
  initialMessages: UIMessage[];
  quotaState?: ChatQuotaState | null;
  votes?: Record<string, MessageVote>;
  models?: ChatModelOption[];
}

/** The canvas's share of the row, in percent. */
const WIDTH = { initial: 45, min: 30, max: 70, step: 2 };

export function ChatWorkspace({
  conversationId,
  initialMessages,
  quotaState = null,
  votes = {},
  models = [],
}: ChatWorkspaceProps) {
  const t = useTranslations("chat");
  const isMobile = useIsMobile();
  const [canvas, setCanvas] = useState<CanvasState | null>(null);
  const [width, setWidth] = useState(WIDTH.initial);
  const [expanded, setExpanded] = useState(false);
  const rowRef = useRef<HTMLDivElement>(null);
  const sendRef = useRef<((text: string) => void) | null>(null);

  const openCanvas = useCallback((ref: CanvasRef) => {
    setCanvas({
      ...ref,
      content: ref.content ?? "",
      status: ref.status ?? "ready",
    });
  }, []);

  const closeCanvas = useCallback(() => {
    setCanvas(null);
    setExpanded(false);
  }, []);

  /** The opening part opens the panel; deltas grow it; the last part settles it. */
  const onArtifact = useCallback((artifact: ChatArtifactData) => {
    setCanvas((current) => {
      const same = current?.id === artifact.id;
      if (artifact.delta !== undefined) {
        if (!same) return current;
        return { ...current!, content: current!.content + artifact.delta };
      }
      if (artifact.status === "streaming") {
        if (same) return current;
        return {
          id: artifact.id,
          kind: artifact.kind,
          title: artifact.title,
          ...(artifact.documentId ? { documentId: artifact.documentId } : {}),
          content: "",
          status: "streaming",
        };
      }
      if (!same) return current;
      return {
        ...current!,
        title: artifact.title,
        ...(artifact.documentId ? { documentId: artifact.documentId } : {}),
        ...(artifact.content !== undefined
          ? { content: artifact.content }
          : {}),
        status: artifact.status,
      };
    });
  }, []);

  function startResize(event: PointerEvent<HTMLDivElement>) {
    const row = rowRef.current;
    if (!row || event.button !== 0) return;
    event.preventDefault();
    const bounds = row.getBoundingClientRect();
    const move = (moveEvent: globalThis.PointerEvent) => {
      const share = ((bounds.right - moveEvent.clientX) / bounds.width) * 100;
      setWidth(Math.min(WIDTH.max, Math.max(WIDTH.min, share)));
    };
    const stop = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", stop);
      document.body.style.removeProperty("cursor");
      document.body.style.removeProperty("user-select");
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", stop);
    document.body.style.cursor = "col-resize";
    document.body.style.userSelect = "none";
  }

  function resizeWithKeys(event: KeyboardEvent<HTMLDivElement>) {
    const delta =
      event.key === "ArrowLeft"
        ? WIDTH.step
        : event.key === "ArrowRight"
          ? -WIDTH.step
          : 0;
    if (!delta) return;
    event.preventDefault();
    setWidth((current) =>
      Math.min(WIDTH.max, Math.max(WIDTH.min, current + delta))
    );
  }

  const thread = (
    <ChatThread
      conversationId={conversationId}
      initialMessages={initialMessages}
      quotaState={quotaState}
      votes={votes}
      models={models}
      variant="page"
      onArtifact={onArtifact}
      onOpenCanvas={openCanvas}
      onCloseCanvas={closeCanvas}
      sendRef={sendRef}
    />
  );

  const panel = canvas ? (
    <ChatCanvas
      canvas={canvas}
      onClose={closeCanvas}
      onSendMessage={(text) => sendRef.current?.(text)}
      onSaved={(documentId, content) =>
        setCanvas((current) =>
          current ? { ...current, documentId, content } : current
        )
      }
      expanded={expanded}
      onToggleExpand={
        isMobile ? undefined : () => setExpanded((value) => !value)
      }
    />
  ) : null;

  const stream =
    canvas?.status === "streaming"
      ? { id: canvas.id, content: canvas.content }
      : null;

  // One tree for every width: the thread is always the first child of
  // the same row, so crossing the breakpoint (a rotation, a resized
  // window) reconciles it in place and keeps the messages in flight.
  // Only what holds the canvas changes — a sheet over the thread on a
  // phone, a column beside it otherwise.
  return (
    <ArtifactStreamProvider value={stream}>
      <div ref={rowRef} className="flex min-h-0 flex-1">
        <div
          className={cn(
            "flex min-h-0 min-w-0 flex-1 flex-col",
            canvas && expanded && !isMobile && "hidden"
          )}
        >
          {thread}
        </div>
        {isMobile ? (
          <Sheet
            open={canvas !== null}
            onOpenChange={(open) => !open && closeCanvas()}
          >
            <SheetContent side="right" className="w-full p-0 sm:max-w-xl">
              <SheetTitle className="sr-only">{t("canvas.title")}</SheetTitle>
              {panel}
            </SheetContent>
          </Sheet>
        ) : canvas ? (
          <aside
            className={cn(
              "relative flex shrink-0 flex-col bg-background",
              expanded ? "flex-1" : "min-w-80 border-l"
            )}
            style={expanded ? undefined : { width: `${width}%` }}
          >
            {expanded ? null : (
              <div
                role="separator"
                aria-orientation="vertical"
                aria-label={t("canvas.resize")}
                aria-valuemin={WIDTH.min}
                aria-valuemax={WIDTH.max}
                aria-valuenow={Math.round(width)}
                tabIndex={0}
                onPointerDown={startResize}
                onKeyDown={resizeWithKeys}
                className="absolute inset-y-0 -left-1.5 z-10 w-3 cursor-col-resize outline-none after:absolute after:inset-y-0 after:left-1/2 after:w-0.5 after:-translate-x-1/2 after:rounded-full after:transition-colors hover:after:bg-ring/60 focus-visible:after:bg-ring"
              />
            )}
            {panel}
          </aside>
        ) : null}
      </div>
    </ArtifactStreamProvider>
  );
}

"use client";

/**
 * The thread — one conversation, streaming, with everything a message
 * can do. The page, the side panel and the floating widget all mount
 * this; they differ only in the shell around it and in `variant`.
 *
 * Owns streaming state via the AI SDK's `useChat` (`@ai-sdk/react`),
 * talking to `app/api/chat/route.ts` over a `DefaultChatTransport`.
 * `initialMessages` comes from the server component so reloading a
 * conversation shows its history immediately, with no client-side
 * fetch-on-mount.
 *
 * Per-turn choices — the model, the agent, extra context a shell wants
 * to send — travel in the request body of each send, never in the
 * transport, so switching models mid-conversation rebuilds nothing and
 * loses no draft.
 *
 * A `?query=` search param seeds the first turn: another surface (the
 * dashboard's prompt bar, a marketing CTA) can mint a conversation id
 * and link straight into a started conversation. It is sent once, only
 * into an empty conversation, so a refresh doesn't replay it.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type React from "react";
import { useTranslations } from "next-intl";
import {
  DefaultChatTransport,
  lastAssistantMessageIsCompleteWithApprovalResponses,
  lastAssistantMessageIsCompleteWithToolCalls,
} from "ai";
import { useChat } from "@ai-sdk/react";
import type { FileUIPart, UIMessage } from "ai";
import { useSearchParams } from "next/navigation";

import {
  isChatDataPart,
  parseChatError,
  type ChatArtifactData,
  type ChatModelOption,
} from "@intelligo-dev/chat/client";

import { useRouter } from "@/i18n/navigation";
import { chatConfig, type ChatMention } from "@/lib/chat-config";
import type { CanvasRef, ToolRendererActions } from "@/lib/chat-renderers";
import { useChatDraft } from "@/hooks/use-chat-draft";
import { useChatShortcuts } from "@/hooks/use-chat-shortcuts";
import { useChatVersions } from "@/hooks/use-chat-versions";

import { ChatEmpty } from "./chat-empty";
import { ChatErrorStrip } from "./chat-error-strip";
import { ChatInput } from "./chat-input";
import {
  CreditStatusBanner,
  type ChatBlock,
  type ChatQuotaState,
} from "./credit-status-banner";
import { MessageList } from "./message-list";
import type { MessageVote } from "./message-actions";

/**
 * A refusal that blocks the composer, or nothing. Admission answers 402
 * with the entitlement port's own code (`insufficient_credits`,
 * `allowance_depleted`…), which is what the banner keys its copy on; a
 * feature gate is a block too. Anything else — a rate limit, a stream
 * failure — is transient and belongs in the error strip.
 */
function refusalFrom(chatError: Error): ChatBlock | null {
  const parsed = parseChatError(chatError);
  if (!parsed) return null;
  if (
    parsed.code !== "QUOTA_EXCEEDED" &&
    parsed.code !== "BILLING_NOT_CONFIGURED" &&
    (parsed.code !== "FEATURE_GATED" ||
      parsed.reasonCode === "model_not_allowed")
  ) {
    return null;
  }
  return { code: parsed.reasonCode ?? parsed.code, message: parsed.error };
}

const MODEL_STORAGE_KEY = "chat:model";

/**
 * When the thread sends the next turn by itself: after the reader
 * answered an approval, or after a card supplied a client-side tool's
 * result. The SDK's tool-calls predicate alone is not enough — a
 * runtime that ends its turn on a server-run tool (a quiz card that
 * waits for a click, a `hasToolCall` stop) also leaves every tool
 * part complete, and re-sending would loop that turn forever. So the
 * tool-calls case counts only when the client put a result in.
 */
function sendWhenClientAnswered(clientAnswered: React.RefObject<boolean>) {
  return (options: { messages: UIMessage[] }) => {
    if (lastAssistantMessageIsCompleteWithApprovalResponses(options))
      return true;
    if (!clientAnswered.current) return false;
    if (!lastAssistantMessageIsCompleteWithToolCalls(options)) return false;
    clientAnswered.current = false;
    return true;
  };
}

export type ChatThreadVariant = "page" | "panel" | "widget";

export interface ChatThreadProps {
  conversationId: string;
  initialMessages: UIMessage[];
  /**
   * Server-rendered credit state. Optional so a deployment that has
   * not wired billing renders the chat unchanged.
   */
  quotaState?: ChatQuotaState | null;
  /** The reader's earlier votes, by message id. */
  votes?: Record<string, MessageVote>;
  /** Models the composer offers. One or none hides the picker. */
  models?: ChatModelOption[];
  variant?: ChatThreadVariant;
  /** Overrides `chatConfig.agent?.id` for this surface. */
  agentId?: string;
  /** Extra body fields on every turn — page context a panel wants the agent to have. */
  body?: Record<string, unknown>;
  autoFocus?: boolean;
  /** The server wrote a title after the first reply. */
  onTitle?: (title: string) => void;
  /** A document streaming into the canvas: the opening part, each delta, the final one. */
  onArtifact?: (artifact: ChatArtifactData) => void;
  /** A card asked for the canvas. */
  onOpenCanvas?: (ref: CanvasRef) => void;
  onCloseCanvas?: () => void;
  /** Read-only: no composer, no actions. The shared page. */
  readOnly?: boolean;
  /** Filled with the thread's send, for a shell that sends on its behalf (the canvas toolbar). */
  sendRef?: React.RefObject<((text: string) => void) | null>;
  className?: string;
}

export function ChatThread({
  conversationId,
  initialMessages,
  quotaState = null,
  votes = {},
  models = [],
  variant = "page",
  agentId,
  body,
  autoFocus = false,
  onTitle,
  onArtifact,
  onOpenCanvas,
  onCloseCanvas,
  readOnly = false,
  sendRef,
  className,
}: ChatThreadProps) {
  const t = useTranslations("chat");
  // Namespace-less: `chatConfig.starters` entries are fully-qualified
  // message keys into the app's whole message tree (see
  // `@/lib/chat-config`'s doc comment), not keys under this item's own
  // "chat" namespace.
  const tAny = useTranslations();
  const searchParams = useSearchParams();
  const router = useRouter();
  const compact = variant !== "page";

  const transport = useMemo(
    () => new DefaultChatTransport({ api: "/api/chat" }),
    []
  );

  const resolvedAgentId = agentId ?? chatConfig.agent?.id;

  // The picked model survives a reload and a conversation switch; the
  // server still decides whether the plan allows it.
  const [modelId, setModelIdState] = useState<string | undefined>(undefined);
  useEffect(() => {
    if (models.length === 0) return;
    let stored: string | null = null;
    try {
      stored = localStorage.getItem(MODEL_STORAGE_KEY);
    } catch {
      stored = null;
    }
    const allowed = models.find((model) => model.id === stored);
    setModelIdState(allowed?.id ?? models[0]!.id);
  }, [models]);
  const setModelId = useCallback((next: string) => {
    setModelIdState(next);
    try {
      localStorage.setItem(MODEL_STORAGE_KEY, next);
    } catch {
      // Remembering the pick is a convenience.
    }
  }, []);

  const bodyRef = useRef<Record<string, unknown>>({});
  bodyRef.current = {
    id: conversationId,
    ...(resolvedAgentId ? { agentId: resolvedAgentId } : {}),
    ...(modelId ? { modelId } : {}),
    ...body,
  };

  // Set by a card that answers a client-side tool; read by the
  // auto-continue predicate.
  const clientAnswered = useRef(false);
  // A thread that opened empty creates its conversation row on the
  // first reply. The shell's history and this page's header are server
  // rendered, so they learn about it from a refresh — once.
  const startedEmpty = useRef(initialMessages.length === 0);
  // A transient `data-chat-status` — "Searching…", "Writing…" — shown
  // as the shimmer under the reply until the next one or the finish.
  const [statusLabel, setStatusLabel] = useState<string | null>(null);

  const {
    messages,
    setMessages,
    sendMessage,
    regenerate,
    addToolOutput,
    addToolApprovalResponse,
    status,
    stop,
    error,
    clearError,
  } = useChat({
    id: conversationId,
    messages: initialMessages,
    transport,
    sendAutomaticallyWhen:
      chatConfig.sendAutomaticallyWhen ??
      sendWhenClientAnswered(clientAnswered),
    onFinish: () => {
      if (!startedEmpty.current) return;
      startedEmpty.current = false;
      router.refresh();
    },
    onData: (part) => {
      if (isChatDataPart(part, "chat-title")) {
        onTitle?.(part.data);
        router.refresh();
        return;
      }
      if (isChatDataPart(part, "chat-status")) {
        setStatusLabel(part.data.done ? null : part.data.label);
        return;
      }
      if (isChatDataPart(part, "chat-artifact")) {
        // Every artifact part — the opening one, each delta, the final
        // `ready` — goes to the canvas, which opens on the first and
        // accumulates the rest.
        onArtifact?.(part.data);
      }
    },
  });

  const isStreaming = status === "streaming" || status === "submitted";

  useEffect(() => {
    if (!isStreaming) setStatusLabel(null);
  }, [isStreaming]);

  const versions = useChatVersions({
    conversationId,
    messages,
    setMessages,
    status,
  });

  const draft = useChatDraft(conversationId);

  /**
   * A refusal the route returned mid-conversation.
   *
   * The server-rendered state is what the page opened with; the
   * balance can run out three turns later, and the reader should not
   * have to reload to be told.
   */
  const [block, setBlock] = useState<ChatBlock | null>(null);
  const blocked = block !== null || quotaState?.allowed === false;

  const starters = useMemo(
    () => (chatConfig.starters ?? []).map((key) => tAny(key)),
    [tAny]
  );

  // In an effect, not in render: `useChat` surfaces the error as
  // state, and setting state while rendering from it is how a render
  // loop starts.
  useEffect(() => {
    if (!error) return;
    const refusal = refusalFrom(error);
    if (refusal) setBlock(refusal);
  }, [error]);

  function friendlyChatError(chatError: Error): string {
    // A non-JSON error response (a proxy's page, a network failure)
    // surfaces as raw text; the generic copy beats showing it.
    return parseChatError(chatError)?.error ?? t("error.generic");
  }

  const send = useCallback(
    (text: string, files: FileUIPart[] = [], mentions: ChatMention[] = []) => {
      const trimmed = text.trim();
      if ((!trimmed && files.length === 0) || isStreaming || blocked) return;
      void sendMessage(
        { text: trimmed, ...(files.length > 0 ? { files } : {}) },
        {
          body: {
            ...bodyRef.current,
            ...(mentions.length > 0
              ? { mentions: mentions.map(({ id, label }) => ({ id, label })) }
              : {}),
          },
        }
      );
      draft.clear();
    },
    [isStreaming, blocked, sendMessage, draft]
  );

  useEffect(() => {
    if (!sendRef) return;
    sendRef.current = (text: string) => send(text);
    return () => {
      sendRef.current = null;
    };
  }, [sendRef, send]);

  const handleRegenerate = useCallback(
    (messageId: string) => {
      if (isStreaming) return;
      versions.beforeRegenerate(messageId);
      void regenerate({ messageId, body: bodyRef.current });
    },
    [isStreaming, versions, regenerate]
  );

  const handleEdit = useCallback(
    (messageId: string, text: string, files: FileUIPart[]) => {
      if (isStreaming) return;
      const at = messages.findIndex((message) => message.id === messageId);
      if (at === -1) return;
      versions.beforeEdit(messageId);
      setMessages(messages.slice(0, at));
      void sendMessage(
        { text, ...(files.length > 0 ? { files } : {}) },
        { body: bodyRef.current }
      );
    },
    [isStreaming, messages, versions, setMessages, sendMessage]
  );

  const editLastUserMessage = useCallback(() => {
    for (let i = messages.length - 1; i >= 0; i--) {
      const message = messages[i]!;
      if (message.role !== "user") continue;
      const text = message.parts
        .filter((part) => part.type === "text")
        .map((part) => (part as { text: string }).text)
        .join("\n\n");
      draft.setValue(text);
      break;
    }
  }, [messages, draft]);

  useChatShortcuts({
    onNewChat: () => router.push("/chat"),
    onStop: stop,
    isStreaming,
  });

  // Prefill from `?query=`, once, and only into a conversation that has
  // no messages yet.
  const prefillSent = useRef(false);
  useEffect(() => {
    if (prefillSent.current) return;
    const query = searchParams.get("query");
    if (!query || messages.length > 0) return;
    prefillSent.current = true;
    void sendMessage({ text: query }, { body: bodyRef.current });
  }, [searchParams, messages.length, sendMessage]);

  // Rebuilt each render on purpose: `send` closes over `isStreaming`,
  // and nothing downstream is memoized on this object.
  const toolActions: ToolRendererActions = {
    sendMessage: (message) =>
      typeof message === "string"
        ? send(message)
        : send(message.text, message.files),
    addToolResult: (args) => {
      clientAnswered.current = true;
      void addToolOutput(args);
    },
    addToolApprovalResponse: (args) => void addToolApprovalResponse(args),
    openCanvas: (ref) => onOpenCanvas?.(ref),
    closeCanvas: () => onCloseCanvas?.(),
  };

  const composer = readOnly ? null : (
    <ChatInput
      conversationId={conversationId}
      value={draft.value}
      onChange={draft.setValue}
      onSend={send}
      onStop={stop}
      onEditLast={editLastUserMessage}
      isStreaming={isStreaming}
      disabled={blocked}
      disabledPlaceholder={t("input.blockedPlaceholder")}
      models={models}
      modelId={modelId}
      onModelChange={setModelId}
      autoFocus={autoFocus}
      compact={compact}
    />
  );

  const isEmpty = messages.length === 0;

  return (
    <div
      className={["flex min-h-0 flex-1 flex-col", className]
        .filter(Boolean)
        .join(" ")}
    >
      {isEmpty && !readOnly ? (
        <ChatEmpty
          starters={starters}
          onStarterSelect={(text) => send(text)}
          composer={composer}
          compact={compact}
        />
      ) : (
        <MessageList
          conversationId={conversationId}
          messages={messages}
          isStreaming={status === "streaming"}
          statusLabel={statusLabel}
          readOnly={readOnly}
          votes={votes}
          versionOf={(messageId) => {
            const version = versions.versionOf(messageId);
            if (!version) return null;
            return {
              index: version.index,
              count: version.count,
              onIndexChange: (index) =>
                versions.select(version.anchorId, index),
            };
          }}
          onRegenerate={readOnly ? undefined : handleRegenerate}
          onEdit={readOnly ? undefined : handleEdit}
          toolActions={readOnly ? undefined : toolActions}
          compact={compact}
        />
      )}
      <CreditStatusBanner quotaState={quotaState} block={block} />
      {error && !block ? (
        <ChatErrorStrip
          message={friendlyChatError(error)}
          onRetry={
            isStreaming
              ? undefined
              : () => {
                  clearError();
                  void regenerate({ body: bodyRef.current });
                }
          }
          onDismiss={clearError}
        />
      ) : null}
      {!isEmpty && !readOnly ? composer : null}
    </div>
  );
}

"use client";

/**
 * The canvas — a document beside the chat: the one a tool is streaming
 * right now, or one a card reopened. The frame is `ai-artifact`;
 * the body is the kind's own component from
 * `lib/chat-canvas-config.tsx`; versions come from the documents
 * table, and an edit saves as a new version.
 *
 * The header is two quiet rows: what the document is (glyph, title,
 * kind and state) with expand and close, then how to work with it — a
 * preview/code switch for content that renders, the version stepper,
 * copy, download, the artifacts page, restore and save.
 */

import { useEffect, useMemo, useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  DownloadIcon,
  ExternalLinkIcon,
  FileTextIcon,
  HistoryIcon,
  Maximize2Icon,
  Minimize2Icon,
  SaveIcon,
} from "lucide-react";
import { toast } from "sonner";

import {
  Artifact,
  ArtifactAction,
  ArtifactActions,
  ArtifactClose,
  ArtifactContent,
  ArtifactDescription,
  ArtifactHeader,
  ArtifactTitle,
} from "@/components/ui/ai-artifact";
import { Button } from "@/components/ui/button";
import { CopyButton } from "@/components/ui/copy-button";
import { Spinner } from "@/components/ui/spinner";
import { Link } from "@/i18n/navigation";
import {
  extensionOf,
  fileNameOf,
  resolveCanvasKind,
} from "@/lib/chat-canvas-config";
import type { CanvasRef } from "@/lib/chat-renderers";
import { cn } from "@/lib/utils";
import { listArtifactVersions, saveArtifactVersion } from "@/actions/chat";

export type CanvasState = CanvasRef & {
  content: string;
  status: "streaming" | "ready" | "error";
};

type Version = { createdAt: string; content: string };

interface ChatCanvasProps {
  canvas: CanvasState;
  onClose: () => void;
  /** Send a message about the document — a kind's toolbar item. */
  onSendMessage: (text: string) => void;
  /** The content changed on disk: a new version was saved. */
  onSaved?: (documentId: string, content: string) => void;
  /** The panel fills the page instead of sharing it with the thread. */
  expanded?: boolean;
  /** Offered where the panel can fill the page. */
  onToggleExpand?: () => void;
}

export function ChatCanvas({
  canvas,
  onClose,
  onSendMessage,
  onSaved,
  expanded = false,
  onToggleExpand,
}: ChatCanvasProps) {
  const t = useTranslations("chat");
  const tAny = useTranslations();
  const kind = resolveCanvasKind(canvas.kind);
  const Content = kind.content;
  const Preview = kind.preview;
  const Icon = kind.icon ?? FileTextIcon;
  const [versions, setVersions] = useState<Version[]>([]);
  const [versionIndex, setVersionIndex] = useState(0);
  const [draft, setDraft] = useState<string | null>(null);
  const [view, setView] = useState<"preview" | "source">("preview");
  const [isSaving, startSaving] = useTransition();

  const documentId = canvas.documentId;
  const canPreview =
    Boolean(Preview) && (kind.previewable?.(canvas.title) ?? true);

  // Versions load once the document is settled; a streaming document
  // has none yet, and a reopened one has whatever was saved.
  useEffect(() => {
    setVersions([]);
    setVersionIndex(0);
    setDraft(null);
    if (!documentId || canvas.status === "streaming") return;
    let cancelled = false;
    void listArtifactVersions(documentId).then((result) => {
      if (cancelled || !result.success) return;
      setVersions(result.data);
    });
    return () => {
      cancelled = true;
    };
  }, [documentId, canvas.status]);

  const content = useMemo(() => {
    if (draft !== null) return draft;
    if (versionIndex > 0 && versions[versionIndex]) {
      return versions[versionIndex]!.content;
    }
    if (canvas.content) return canvas.content;
    return versions[0]?.content ?? "";
  }, [draft, versionIndex, versions, canvas.content]);

  const isLatest = versionIndex === 0;
  const isReadonly = canvas.status === "streaming" || !isLatest || !documentId;
  const showPreview =
    canPreview && view === "preview" && canvas.status !== "streaming";

  function selectVersion(index: number) {
    setDraft(null);
    setVersionIndex(index);
  }

  /** An older version becomes the draft of the next one. */
  function restore() {
    const older = versions[versionIndex]?.content;
    if (older === undefined) return;
    setVersionIndex(0);
    setDraft(older);
  }

  function download() {
    const link = document.createElement("a");
    if (canvas.kind === "image") {
      link.href = content;
    } else {
      link.href = URL.createObjectURL(
        new Blob([content], {
          type: canvas.kind === "sheet" ? "text/csv" : "text/plain",
        })
      );
    }
    link.download = fileNameOf(canvas.title, kind);
    link.click();
    if (link.href.startsWith("blob:")) URL.revokeObjectURL(link.href);
  }

  function save() {
    if (!documentId || draft === null) return;
    startSaving(async () => {
      const result = await saveArtifactVersion({
        documentId,
        title: canvas.title,
        kind: canvas.kind,
        content: draft,
      });
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      toast.success(t("canvas.saved"));
      onSaved?.(documentId, draft);
      setDraft(null);
      const refreshed = await listArtifactVersions(documentId);
      if (refreshed.success) setVersions(refreshed.data);
      setVersionIndex(0);
    });
  }

  const extension =
    canvas.kind === "code" ? extensionOf(canvas.title) : undefined;
  const description =
    canvas.status === "streaming" ? (
      <>
        <Spinner className="size-3" />
        {t("artifactCard.streaming")}
      </>
    ) : draft !== null ? (
      <>
        <span aria-hidden="true" className="size-1.5 rounded-full bg-warning" />
        {t("canvas.unsavedChanges")}
      </>
    ) : (
      [kind.labelKey ? tAny(kind.labelKey) : null, extension]
        .filter(Boolean)
        .join(" · ")
    );

  return (
    <Artifact className="h-full rounded-none border-0 shadow-none">
      <ArtifactHeader className="flex-col items-stretch gap-1.5 bg-transparent px-3 pt-2.5 pb-2">
        <div className="flex min-w-0 items-center gap-2.5">
          <span
            aria-hidden="true"
            className="grid size-8 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground"
          >
            <Icon className="size-4" />
          </span>
          <div className="min-w-0 flex-1">
            <ArtifactTitle className="truncate leading-5">
              {canvas.title}
            </ArtifactTitle>
            <ArtifactDescription className="flex min-h-4 items-center gap-1.5 truncate text-xs leading-4">
              {description}
            </ArtifactDescription>
          </div>
          {onToggleExpand ? (
            <ArtifactAction
              label={expanded ? t("canvas.collapse") : t("canvas.expand")}
              tooltip={expanded ? t("canvas.collapse") : t("canvas.expand")}
              icon={expanded ? Minimize2Icon : Maximize2Icon}
              onClick={onToggleExpand}
            />
          ) : null}
          <ArtifactClose label={t("canvas.close")} onClick={onClose} />
        </div>

        <div className="flex min-w-0 flex-wrap items-center gap-1">
          {canPreview ? (
            <div
              role="group"
              aria-label={t("canvas.view")}
              className="flex items-center rounded-lg bg-muted p-0.5"
            >
              {(["preview", "source"] as const).map((option) => (
                <button
                  key={option}
                  type="button"
                  aria-pressed={view === option}
                  onClick={() => setView(option)}
                  className={cn(
                    "h-6 rounded-md px-2 text-xs font-medium text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring",
                    view === option && "bg-background text-foreground shadow-xs"
                  )}
                >
                  {option === "preview"
                    ? t("canvas.preview")
                    : t("canvas.source")}
                </button>
              ))}
            </div>
          ) : null}

          {versions.length > 1 ? (
            <div
              role="group"
              aria-label={t("canvas.version")}
              className="flex items-center"
            >
              <ArtifactAction
                label={t("canvas.olderVersion")}
                icon={ChevronLeftIcon}
                disabled={versionIndex >= versions.length - 1}
                onClick={() => selectVersion(versionIndex + 1)}
              />
              <span className="min-w-10 text-center text-xs text-muted-foreground tabular-nums">
                {t("canvas.versionOf", {
                  index: versions.length - versionIndex,
                  count: versions.length,
                })}
              </span>
              <ArtifactAction
                label={t("canvas.newerVersion")}
                icon={ChevronRightIcon}
                disabled={isLatest}
                onClick={() => selectVersion(versionIndex - 1)}
              />
            </div>
          ) : null}

          <ArtifactActions className="ml-auto">
            {kind.actions?.map((action) => (
              <ArtifactAction
                key={action.labelKey}
                label={tAny(action.labelKey)}
                tooltip={tAny(action.labelKey)}
                icon={action.icon}
                onClick={() =>
                  void action.onClick({
                    content,
                    title: canvas.title,
                    ...(documentId ? { documentId } : {}),
                  })
                }
              />
            ))}
            <CopyButton
              value={content}
              label={t("canvas.copy")}
              copiedLabel={t("actions.copied")}
              onCopyError={() => toast.error(t("actions.copyFailed"))}
              size="icon-sm"
              variant="ghost"
            />
            <ArtifactAction
              label={t("canvas.download")}
              tooltip={t("canvas.download")}
              icon={DownloadIcon}
              disabled={!content || canvas.status === "streaming"}
              onClick={download}
            />
            {documentId ? (
              <ArtifactAction
                label={t("canvas.openInArtifacts")}
                tooltip={t("canvas.openInArtifacts")}
                icon={ExternalLinkIcon}
                render={
                  <Link
                    href={`/artifacts?document=${encodeURIComponent(documentId)}`}
                  />
                }
                nativeButton={false}
              />
            ) : null}
            {!isLatest ? (
              <Button
                size="xs"
                variant="outline"
                type="button"
                onClick={restore}
              >
                <HistoryIcon data-icon="inline-start" />
                {t("canvas.restore")}
              </Button>
            ) : null}
            {draft !== null ? (
              <Button
                size="xs"
                type="button"
                onClick={save}
                disabled={isSaving}
                aria-busy={isSaving || undefined}
              >
                {isSaving ? (
                  <Spinner data-icon="inline-start" />
                ) : (
                  <SaveIcon data-icon="inline-start" />
                )}
                {t("canvas.save")}
              </Button>
            ) : null}
          </ArtifactActions>
        </div>
      </ArtifactHeader>
      <ArtifactContent className={cn("min-h-0", showPreview && "p-3")}>
        {showPreview && Preview ? (
          <Preview
            content={content}
            status={canvas.status}
            title={canvas.title}
            isReadonly
          />
        ) : (
          <Content
            content={content}
            status={canvas.status}
            title={canvas.title}
            isReadonly={isReadonly}
            onChange={isReadonly ? undefined : setDraft}
          />
        )}
      </ArtifactContent>
      {kind.toolbar?.length ? (
        <div className="flex flex-wrap gap-2 border-t px-4 py-2">
          {kind.toolbar.map((item) => (
            <Button
              key={item.labelKey}
              size="xs"
              variant="outline"
              type="button"
              onClick={() => onSendMessage(item.message)}
            >
              {tAny(item.labelKey)}
            </Button>
          ))}
        </div>
      ) : null}
    </Artifact>
  );
}

"use client";

/**
 * The canvas's text editor: ProseMirror over a markdown document.
 *
 * Markdown in, markdown out — `prosemirror-markdown`'s parser builds
 * the document and its serializer writes it back, so what the tool
 * streamed and what the reader saves are the same text the model
 * reads. While a document streams in, every update replaces the
 * document without touching the reader's draft; once settled, edits
 * flow up through `onChange`.
 *
 * Loaded lazily by `lib/chat-canvas-config.tsx`: a reader who never
 * opens a text document never downloads the editor.
 */

import { useEffect, useRef } from "react";
import { exampleSetup } from "prosemirror-example-setup";
import { inputRules, textblockTypeInputRule } from "prosemirror-inputrules";
import {
  defaultMarkdownParser,
  defaultMarkdownSerializer,
  schema,
} from "prosemirror-markdown";
import { EditorState, type Transaction } from "prosemirror-state";
import { EditorView } from "prosemirror-view";

import type { CanvasContentProps } from "@/lib/chat-canvas-config";

function headingRule(level: number) {
  return textblockTypeInputRule(
    new RegExp(`^(#{1,${level}})\\s$`),
    schema.nodes.heading!,
    () => ({ level })
  );
}

function parse(content: string) {
  return defaultMarkdownParser.parse(content) ?? schema.node("doc", null, []);
}

/**
 * The document's typography, spelled out: the theme ships no typography
 * plugin, so `prose` classes would style nothing — lists lose their
 * numbers, headings their size.
 */
const EDITOR_CLASS = [
  "text-sm leading-relaxed text-foreground",
  "[&_.ProseMirror]:min-h-64 [&_.ProseMirror]:outline-none",
  "[&_.ProseMirror>*+*]:mt-3",
  "[&_.ProseMirror_h1]:text-2xl [&_.ProseMirror_h1]:font-semibold [&_.ProseMirror_h1]:tracking-tight",
  "[&_.ProseMirror_h2]:text-xl [&_.ProseMirror_h2]:font-semibold",
  "[&_.ProseMirror_h3]:text-base [&_.ProseMirror_h3]:font-semibold",
  "[&_.ProseMirror_ol]:list-decimal [&_.ProseMirror_ol]:pl-6",
  "[&_.ProseMirror_ul]:list-disc [&_.ProseMirror_ul]:pl-6",
  "[&_.ProseMirror_li]:my-1 [&_.ProseMirror_li>p]:m-0",
  "[&_.ProseMirror_blockquote]:border-l-2 [&_.ProseMirror_blockquote]:pl-4 [&_.ProseMirror_blockquote]:text-muted-foreground",
  "[&_.ProseMirror_code]:rounded [&_.ProseMirror_code]:bg-muted [&_.ProseMirror_code]:px-1 [&_.ProseMirror_code]:font-mono [&_.ProseMirror_code]:text-xs",
  "[&_.ProseMirror_pre]:overflow-x-auto [&_.ProseMirror_pre]:rounded-md [&_.ProseMirror_pre]:bg-muted [&_.ProseMirror_pre]:p-3",
  "[&_.ProseMirror_a]:underline [&_.ProseMirror_a]:underline-offset-4",
  "[&_.ProseMirror_hr]:border-border",
].join(" ");

export default function TextEditor({
  content,
  status,
  isReadonly,
  onChange,
}: CanvasContentProps) {
  const container = useRef<HTMLDivElement>(null);
  const view = useRef<EditorView | null>(null);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  const readonlyRef = useRef(isReadonly);
  readonlyRef.current = isReadonly;

  useEffect(() => {
    if (!container.current || view.current) return;
    const state = EditorState.create({
      doc: parse(content),
      plugins: [
        ...exampleSetup({ schema, menuBar: false }),
        inputRules({ rules: [1, 2, 3, 4, 5, 6].map(headingRule) }),
      ],
    });
    view.current = new EditorView(container.current, {
      state,
      editable: () => !readonlyRef.current,
      dispatchTransaction(transaction: Transaction) {
        const editor = view.current;
        if (!editor) return;
        editor.updateState(editor.state.apply(transaction));
        if (transaction.docChanged && !transaction.getMeta("external")) {
          onChangeRef.current?.(
            defaultMarkdownSerializer.serialize(editor.state.doc)
          );
        }
      },
    });
    return () => {
      view.current?.destroy();
      view.current = null;
    };
    // The editor mounts once; content updates flow through the effect below.
  }, []);

  // External content (a stream, a version switch) replaces the document.
  useEffect(() => {
    const editor = view.current;
    if (!editor) return;
    const current = defaultMarkdownSerializer.serialize(editor.state.doc);
    if (current === content) return;
    if (status !== "streaming" && !isReadonly && editor.hasFocus()) return;
    const next = parse(content);
    const transaction = editor.state.tr.replaceWith(
      0,
      editor.state.doc.content.size,
      next.content
    );
    transaction.setMeta("external", true);
    editor.dispatch(transaction);
  }, [content, status, isReadonly]);

  return <div ref={container} className={EDITOR_CLASS} />;
}

"use client";

/**
 * The canvas's code editor: CodeMirror 6, with the language picked from
 * the document's file extension and the theme following the app's.
 * External content — a stream, a version switch — replaces the buffer
 * as a remote change so it never re-enters as an edit.
 *
 * Loaded lazily by `lib/chat-canvas-config.tsx`.
 */

import { useEffect, useMemo, useRef } from "react";
import { javascript } from "@codemirror/lang-javascript";
import { python } from "@codemirror/lang-python";
import { Compartment, EditorState, Transaction } from "@codemirror/state";
import { oneDark } from "@codemirror/theme-one-dark";
import { EditorView } from "@codemirror/view";
import { basicSetup } from "codemirror";
import { useTheme } from "next-themes";

import type { CanvasContentProps } from "@/lib/chat-canvas-config";

function languageFor(title: string) {
  const extension = title.split(".").pop()?.toLowerCase() ?? "";
  switch (extension) {
    case "ts":
      return javascript({ typescript: true });
    case "tsx":
      return javascript({ typescript: true, jsx: true });
    case "jsx":
      return javascript({ jsx: true });
    case "js":
    case "mjs":
    case "cjs":
      return javascript();
    case "py":
      return python();
    default:
      return [];
  }
}

const lightTheme = EditorView.theme({
  "&": { backgroundColor: "transparent", fontSize: "0.875rem" },
  ".cm-gutters": { backgroundColor: "transparent", border: "none" },
});

export default function CodeEditor({
  content,
  status,
  title,
  isReadonly,
  onChange,
}: CanvasContentProps) {
  const container = useRef<HTMLDivElement>(null);
  const view = useRef<EditorView | null>(null);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  const { resolvedTheme } = useTheme();
  const themeCompartment = useMemo(() => new Compartment(), []);
  const readonlyCompartment = useMemo(() => new Compartment(), []);
  const languageCompartment = useMemo(() => new Compartment(), []);

  useEffect(() => {
    if (!container.current || view.current) return;
    const state = EditorState.create({
      doc: content,
      extensions: [
        basicSetup,
        languageCompartment.of(languageFor(title)),
        themeCompartment.of(resolvedTheme === "dark" ? oneDark : lightTheme),
        readonlyCompartment.of(EditorState.readOnly.of(isReadonly)),
        EditorView.updateListener.of((update) => {
          if (!update.docChanged) return;
          const local = update.transactions.some(
            (transaction) => !transaction.annotation(Transaction.remote)
          );
          if (local) onChangeRef.current?.(update.state.doc.toString());
        }),
      ],
    });
    view.current = new EditorView({ state, parent: container.current });
    return () => {
      view.current?.destroy();
      view.current = null;
    };
    // Mounts once; the compartments below follow prop changes.
  }, []);

  useEffect(() => {
    view.current?.dispatch({
      effects: themeCompartment.reconfigure(
        resolvedTheme === "dark" ? oneDark : lightTheme
      ),
    });
  }, [resolvedTheme, themeCompartment]);

  useEffect(() => {
    view.current?.dispatch({
      effects: readonlyCompartment.reconfigure(
        EditorState.readOnly.of(isReadonly)
      ),
    });
  }, [isReadonly, readonlyCompartment]);

  useEffect(() => {
    view.current?.dispatch({
      effects: languageCompartment.reconfigure(languageFor(title)),
    });
  }, [title, languageCompartment]);

  useEffect(() => {
    const editor = view.current;
    if (!editor) return;
    const current = editor.state.doc.toString();
    if (current === content) return;
    if (status !== "streaming" && !isReadonly && editor.hasFocus) return;
    editor.dispatch({
      changes: { from: 0, to: current.length, insert: content },
      annotations: [Transaction.remote.of(true)],
    });
  }, [content, status, isReadonly]);

  return <div ref={container} className="min-h-64 text-sm" />;
}

"use client";

/**
 * The canvas's spreadsheet: a CSV document on react-data-grid. The
 * grid is padded to a working size so an empty sheet still looks like
 * one; every edit is serialised back to CSV for `onChange`.
 *
 * Loaded lazily by `lib/chat-canvas-config.tsx`.
 */

import { useEffect, useMemo, useState } from "react";
import { parse, unparse } from "papaparse";
import { DataGrid, renderTextEditor, type Column } from "react-data-grid";
import { useTheme } from "next-themes";

import "react-data-grid/lib/styles.css";

import type { CanvasContentProps } from "@/lib/chat-canvas-config";

const MIN_ROWS = 40;
const MIN_COLS = 16;

type Row = { id: number; [column: string]: string | number };

function toRows(content: string): string[][] {
  const parsed = content
    ? parse<string[]>(content, { skipEmptyLines: true }).data
    : [];
  const width = Math.max(MIN_COLS, ...parsed.map((row) => row.length));
  const rows = parsed.map((row) => {
    const padded = [...row];
    while (padded.length < width) padded.push("");
    return padded;
  });
  while (rows.length < MIN_ROWS) rows.push(new Array<string>(width).fill(""));
  return rows;
}

function columnName(index: number): string {
  let name = "";
  let n = index;
  do {
    name = String.fromCharCode(65 + (n % 26)) + name;
    n = Math.floor(n / 26) - 1;
  } while (n >= 0);
  return name;
}

export default function SheetEditor({
  content,
  isReadonly,
  onChange,
}: CanvasContentProps) {
  const { resolvedTheme } = useTheme();
  const cells = useMemo(() => toRows(content), [content]);
  const width = cells[0]?.length ?? MIN_COLS;

  const columns = useMemo<Column<Row>[]>(() => {
    const rowNumber: Column<Row> = {
      key: "rowNumber",
      name: "",
      frozen: true,
      width: 48,
      renderCell: ({ rowIdx }) => rowIdx + 1,
      cellClass: "bg-muted text-muted-foreground",
      headerCellClass: "bg-muted",
    };
    const data = Array.from({ length: width }, (_, index): Column<Row> => ({
      key: String(index),
      name: columnName(index),
      width: 120,
      resizable: true,
      renderEditCell: isReadonly ? undefined : renderTextEditor,
      headerCellClass: "bg-muted",
    }));
    return [rowNumber, ...data];
  }, [width, isReadonly]);

  const initialRows = useMemo<Row[]>(
    () =>
      cells.map((row, rowIndex) => {
        const record: Row = { id: rowIndex };
        row.forEach((cell: string, columnIndex: number) => {
          record[String(columnIndex)] = cell;
        });
        return record;
      }),
    [cells]
  );

  const [rows, setRows] = useState<Row[]>(initialRows);
  useEffect(() => setRows(initialRows), [initialRows]);

  function handleRowsChange(next: Row[]) {
    setRows(next);
    const table = next.map((row) =>
      Array.from({ length: width }, (_, index) =>
        String(row[String(index)] ?? "")
      )
    );
    // Trailing empty rows and columns are padding, not content.
    while (table.length && table[table.length - 1]!.every((cell) => !cell)) {
      table.pop();
    }
    onChange?.(unparse(table));
  }

  return (
    <DataGrid
      className={
        resolvedTheme === "dark" ? "rdg-dark h-full" : "rdg-light h-full"
      }
      columns={columns}
      rows={rows}
      rowKeyGetter={(row) => row.id}
      onRowsChange={isReadonly ? undefined : handleRowsChange}
      defaultColumnOptions={{ resizable: true }}
    />
  );
}

