  onDismiss: () => void;
}

export function ChatErrorStrip({
  message,
  onRetry,
  onDismiss,
}: ChatErrorStripProps) {
  const t = useTranslations("chat");

  return (
    <Alert variant="destructive" className="mx-auto mb-2 w-full max-w-3xl">
      <AlertTriangleIcon />
      <AlertDescription>{message}</AlertDescription>
