"use client";

/**
 * A run of the agent's own work — its reasoning and the tool calls
 * between its words — as one activity stream: live while it runs, then
 * a one-line summary ("Searched the web ▸") the reader opens on demand.
 *
 * Each call becomes a row. The default reads the call itself: an input
 * with a `query` is a search whose results are the sources the output
 * carries; anything else is the tool's label and its first string
 * input. A tool's entry in `TOOL_RENDERERS` can name the call (`label`)
 * or build its row (`activity`). The raw input and output stay one
 * click away, under the row — never on the page by default.
 */

import { getToolName, isReasoningUIPart, isToolUIPart } from "ai";
import type { UIMessage } from "ai";
import { useTranslations } from "next-intl";
import { Streamdown } from "streamdown";

import {
  AgentActivity,
  type AgentActivityItem,
} from "@/components/ui/ai-agent-activity";
import { CodeBlock } from "@/components/ui/ai-code-block";
import {
  Reasoning,
  ReasoningContent,
  ReasoningTrigger,
} from "@/components/ui/ai-reasoning";
import {
  resolveToolRenderer,
  toolLabel,
  type ToolActivityRow,
  type ToolRendererProps,
} from "@/lib/chat-renderers";
import {
  isSettledToolState,
  primaryInput,
  sourceDomain,
  sourcesFromToolOutput,
  titleFromUrl,
  type PartAt,
} from "@/lib/message-parts";

type Part = UIMessage["parts"][number];

/** Results shown under a search before "+N more". */
const VISIBLE_RESULTS = 4;

interface ToolActivityProps {
  parts: PartAt<Part>[];
  working: boolean;
  /** The renderer props for one tool part — the same ones a card gets. */
  toolProps: (part: Part) => ToolRendererProps;
}

export function ToolActivity({ parts, working, toolProps }: ToolActivityProps) {
  const t = useTranslations("chat");
  const tAny = useTranslations();

  // Thinking alone reads as thinking: the reasoning disclosure, timed.
  if (parts.every(({ part }) => isReasoningUIPart(part))) {
    const text = parts
      .map(({ part }) => (part as { text: string }).text)
      .join("\n\n");
    return (
      <Reasoning isStreaming={working}>
        <ReasoningTrigger
          getThinkingMessage={(streaming, duration) =>
            streaming
              ? t("message.thinking")
              : duration === undefined
                ? t("message.thoughtBriefly")
                : t("message.thoughtFor", { seconds: duration })
          }
        />
        <ReasoningContent>{text}</ReasoningContent>
      </Reasoning>
    );
  }

  const items: AgentActivityItem[] = [];
  let searches = 0;
  let tools = 0;
  let liveLabel: string | null = null;

  for (const { index, part } of parts) {
    const id = `part-${index}`;

    if (isReasoningUIPart(part)) {
      items.push({
        id,
        type: "text",
        content: (
          <Streamdown className="text-sm text-muted-foreground [&_p]:my-1 first:[&_p]:mt-0 last:[&_p]:mb-0">
            {part.text}
          </Streamdown>
        ),
      });
      continue;
    }

    if (!isToolUIPart(part)) continue;
    const props = toolProps(part);
    const renderer = resolveToolRenderer(getToolName(part));
    const name = renderer.label
      ? tAny(renderer.label)
      : toolLabel(props.toolName);
    const row =
      renderer.activity?.(props) ??
      defaultRow(props, name, renderer.sources, t);
    const details = <ToolCallDetails {...props} />;

    if (row.type === "search") searches += 1;
    else tools += 1;
    if (row.status === "running") {
      liveLabel =
        row.type === "search" ? t("toolActivity.searching") : `${name}…`;
    }
    items.push({
      ...row,
      id,
      details: row.details ?? details,
    } as AgentActivityItem);
  }

  const summary =
    searches > 0 && tools > 0
      ? t("toolActivity.searchedAndRan", { count: tools })
      : searches > 0
        ? t("toolActivity.searched")
        : tools > 0
          ? t("toolActivity.ranTools", { count: tools })
          : t("toolActivity.thought");

  return (
    <AgentActivity
      className="max-w-2xl"
      // Room for a row the reader opened onto its call.
      maxHeight={working ? 208 : 480}
      items={items}
      status={working ? "working" : "complete"}
      activeLabel={liveLabel ?? t("toolActivity.working")}
      summary={summary}
      moreLabel={(count) => t("toolActivity.more", { count })}
    />
  );
}

function defaultRow(
  props: ToolRendererProps,
  name: string,
  readSources:
    ((output: unknown) => ReturnType<typeof sourcesFromToolOutput>) | undefined,
  t: (key: string, values?: Record<string, string | number>) => string
): ToolActivityRow {
  const status =
    props.state === "output-error" || props.state === "output-denied"
      ? "error"
      : isSettledToolState(props.state)
        ? "complete"
        : "running";
  const input = props.input as Record<string, unknown> | undefined;
  const query = typeof input?.query === "string" ? input.query : undefined;

  if (query !== undefined && status !== "error") {
    const sources = (readSources ?? sourcesFromToolOutput)(props.output);
    return {
      type: "search",
      query,
      status,
      results: sources.slice(0, VISIBLE_RESULTS).map((source, index) => {
        const domain = sourceDomain(source);
        const title =
          (source.title && source.title !== domain
            ? source.title
            : undefined) ?? titleFromUrl(source.url);
        return {
          id: source.url ?? `${index}`,
          title: title ?? domain ?? source.url ?? "",
          ...(domain && title ? { domain } : {}),
          ...(source.url ? { url: source.url } : {}),
        };
      }),
      moreCount: Math.max(0, sources.length - VISIBLE_RESULTS),
    };
  }

  return {
    type: "tool",
    action: name,
    status,
    target:
      props.state === "output-denied"
        ? t("toolActivity.denied", { tool: name })
        : props.state === "output-error"
          ? (props.errorText ?? t("toolActivity.failed", { tool: name }))
          : primaryInput(props.input),
  };
}

/** The call as it happened: what went in, what came back. */
function ToolCallDetails({ input, output, errorText }: ToolRendererProps) {
  const t = useTranslations("chat");
  const blocks: Array<{
    label: string;
    code: string;
    language: "json" | "text";
  }> = [];
  if (input !== undefined) {
    blocks.push({
      label: t("toolActivity.input"),
      code: stringify(input),
      language: "json",
    });
  }
  if (errorText) {
    blocks.push({
      label: t("toolActivity.error"),
      code: errorText,
      language: "text",
    });
  } else if (output !== undefined) {
    blocks.push({
      label: t("toolActivity.output"),
      code: stringify(output),
      language: "json",
    });
  }
  if (blocks.length === 0) return null;

  return (
    <div className="grid gap-2">
      {blocks.map((block) => (
        <div key={block.label} className="grid gap-1">
          <span className="text-xs font-medium text-muted-foreground">
            {block.label}
          </span>
          <CodeBlock
            code={block.code}
            language={block.language}
            className="text-xs [&_pre]:max-h-48 [&_pre]:overflow-auto [&_pre]:p-2.5! [&_pre]:text-xs! [&_pre]:break-words [&_pre]:whitespace-pre-wrap"
          />
        </div>
      ))}
    </div>
  );
}

function stringify(value: unknown): string {
  return typeof value === "string" ? value : JSON.stringify(value, null, 2);
}

"use client";

/**
 * A document in the transcript: the kind's glyph, its title, what it
 * is ("Code · py"), and — while it is being written — the last lines
 * arriving under a fade. The whole card opens the document in the
 * canvas, or on the artifacts page where there is no canvas.
 *
 * The streamed text reaches a card two ways: a tool's own input as the
 * model writes it (`saveArtifact`), or the canvas's live content for a
 * document `createArtifactWriter` streams, which `ChatWorkspace`
 * shares through `ArtifactStreamProvider`.
 */

import { createContext, useContext, type ReactNode } from "react";
import { useTranslations } from "next-intl";
import { ChevronRightIcon, FileTextIcon } from "lucide-react";

import { ShimmerText } from "@/components/ui/ai-shimmer-text";
import { Link } from "@/i18n/navigation";
import { extensionOf, resolveCanvasKind } from "@/lib/chat-canvas-config";
import { cn } from "@/lib/utils";

type ArtifactStream = { id: string; content: string } | null;

const ArtifactStreamContext = createContext<ArtifactStream>(null);

/** Shares the document streaming into the canvas with its card in the transcript. */
export function ArtifactStreamProvider({
  value,
  children,
}: {
  value: ArtifactStream;
  children: ReactNode;
}) {
  return (
    <ArtifactStreamContext.Provider value={value}>
      {children}
    </ArtifactStreamContext.Provider>
  );
}

/** The streamed content of the document with this id, while it streams. */
export function useArtifactStream(id: string | undefined): string | undefined {
  const stream = useContext(ArtifactStreamContext);
  return id && stream?.id === id ? stream.content : undefined;
}

/** The lines shown under a card while the document is written. */
const PREVIEW_LINES = 4;

function tail(text: string): string {
  return text.trimEnd().split("\n").slice(-PREVIEW_LINES).join("\n");
}

/** Alpha-only: the older lines fade out above the newest. */
const PREVIEW_MASK = "linear-gradient(to bottom, transparent, black 70%)";

export interface ArtifactCardProps {
  title: string;
  kind: string;
  status: "streaming" | "ready" | "error";
  error?: string;
  /** The document's text so far, for the live preview while it streams. */
  preview?: string;
  /** Opens the document — the canvas. */
  onOpen?: () => void;
  /** Where the document lives when there is no canvas to open it in. */
  href?: string;
  className?: string;
}

export function ArtifactCard({
  title,
  kind: kindName,
  status,
  error,
  preview,
  onOpen,
  href,
  className,
}: ArtifactCardProps) {
  const t = useTranslations("chat");
  const tAny = useTranslations();
  const kind = resolveCanvasKind(kindName);
  const Icon = kind.icon ?? FileTextIcon;
  const extension = kindName === "code" ? extensionOf(title) : undefined;
  const interactive = Boolean(onOpen || href);
  const previewText = status === "streaming" && preview ? tail(preview) : "";

  const subtitle =
    status === "streaming" ? (
      <ShimmerText role={undefined}>{t("artifactCard.streaming")}</ShimmerText>
    ) : status === "error" ? (
      (error ?? t("artifactCard.failed"))
    ) : (
      [kind.labelKey ? tAny(kind.labelKey) : null, extension]
        .filter(Boolean)
        .join(" · ")
    );

  const content = (
    <>
      <span className="flex min-w-0 items-center gap-3 p-3">
        <span
          aria-hidden="true"
          className="grid size-10 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground"
        >
          <Icon className="size-5" />
        </span>
        <span className="grid min-w-0 flex-1 gap-0.5">
          <span className="truncate text-sm leading-5 font-medium text-foreground">
            {title}
          </span>
          <span
            className={cn(
              "truncate text-xs leading-4 text-muted-foreground",
              status === "error" && "text-destructive"
            )}
          >
            {subtitle}
          </span>
        </span>
        {interactive ? (
          <ChevronRightIcon
            aria-hidden="true"
            className="size-4 shrink-0 text-muted-foreground transition-transform group-hover/artifact:translate-x-0.5"
          />
        ) : null}
      </span>
      {previewText ? (
        <span
          aria-hidden="true"
          className="block max-h-20 overflow-hidden border-t px-3 py-2 font-mono text-xs leading-4 whitespace-pre-wrap text-muted-foreground"
          style={{ maskImage: PREVIEW_MASK, WebkitMaskImage: PREVIEW_MASK }}
        >
          {previewText}
        </span>
      ) : null}
    </>
  );

  const classes = cn(
    "group/artifact flex w-full max-w-md flex-col overflow-hidden rounded-xl border bg-card text-left",
    interactive &&
      "outline-none transition-colors hover:bg-muted/40 focus-visible:ring-2 focus-visible:ring-ring",
    className
  );

  if (onOpen) {
    return (
      <button
        type="button"
        data-slot="artifact-card"
        className={classes}
        onClick={onOpen}
      >
        {content}
      </button>
    );
  }
  if (href) {
    return (
      <Link data-slot="artifact-card" href={href} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <div
      data-slot="artifact-card"
      className={classes}
      aria-busy={status === "streaming" || undefined}
    >
      {content}
    </div>
  );
}

"use client";

/**
 * The composer, on `ai-prompt-input`: an autosizing
 * textarea that sends on Enter, attachments by "+" / paste / drop when
 * `chatConfig.attachments` allows them, a model picker when the page
 * offers more than one, and a submit that becomes stop while a reply
 * streams. The draft is the thread's, so nothing typed is lost to a
 * model switch or a navigation.
 *
 * ArrowUp in an empty composer loads the last message the reader sent,
 * to edit and re-send — the shell habit a chat inherits.
 */

import { useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";
import type { FileUIPart } from "ai";

import type { ChatModelOption } from "@intelligo-dev/chat/client";

import { ComposerMenu } from "@/components/ui/ai-composer-menu";
import { SpeechInput } from "@/components/ui/ai-speech-input";
import { useComposerMenu } from "@/hooks/use-composer-menu";

import {
  PromptInput,
  PromptInputActionAddAttachments,
  PromptInputActionMenu,
  PromptInputActionMenuContent,
  PromptInputActionMenuTrigger,
  PromptInputAttachment,
  PromptInputAttachments,
  PromptInputFooter,
  PromptInputSelect,
  PromptInputSelectContent,
  PromptInputSelectItem,
  PromptInputSelectTrigger,
  PromptInputSelectValue,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
  type PromptInputError,
} from "@/components/ui/ai-prompt-input";
import { chatConfig, type ChatMention } from "@/lib/chat-config";

interface ChatInputProps {
  conversationId: string;
  value: string;
  onChange: (value: string) => void;
  onSend: (text: string, files: FileUIPart[], mentions: ChatMention[]) => void;
  onStop: () => void;
  onEditLast?: () => void;
  isStreaming: boolean;
  /**
   * Stops the composer accepting a turn that will be refused — out of
   * credits, or behind a feature gate. The banner above says why; this
   * is what keeps someone from writing a paragraph into a request the
   * route has already told us it will reject.
   */
  disabled?: boolean;
  /** Placeholder to show instead of the usual one while disabled. */
  disabledPlaceholder?: string;
  models?: ChatModelOption[];
  modelId?: string;
  onModelChange?: (modelId: string) => void;
  autoFocus?: boolean;
  compact?: boolean;
}

const DEFAULT_UPLOAD_URL = "/api/chat/upload";

/** In `stored` mode a picked file uploads first; the message carries its app URL. */
async function upload(
  file: FileUIPart,
  uploadUrl: string
): Promise<FileUIPart> {
  const blob = await (await fetch(file.url)).blob();
  const form = new FormData();
  form.set("file", blob, file.filename ?? "file");
  const response = await fetch(uploadUrl, { method: "POST", body: form });
  if (!response.ok) throw new Error(`upload failed: ${response.status}`);
  const result = (await response.json()) as {
    url: string;
    mediaType: string;
    filename: string;
  };
  return {
    type: "file",
    url: result.url,
    mediaType: result.mediaType,
    filename: result.filename,
  };
}

export function ChatInput({
  conversationId,
  value,
  onChange,
  onSend,
  onStop,
  onEditLast,
  isStreaming,
  disabled = false,
  disabledPlaceholder,
  models = [],
  modelId,
  onModelChange,
  autoFocus = false,
  compact = false,
}: ChatInputProps) {
  const t = useTranslations("chat");
  const [uploading, setUploading] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const attachments = chatConfig.attachments;
  const placeholder =
    disabled && disabledPlaceholder
      ? disabledPlaceholder
      : t("input.placeholder");

  useEffect(() => {
    if (autoFocus) textareaRef.current?.focus();
  }, [autoFocus]);

  const menu = useComposerMenu({
    value,
    setValue: onChange,
    conversationId,
    send: (text) => onSend(text, [], []),
    textareaRef,
  });

  function reportError(error: PromptInputError) {
    if (error.code === "max_files") {
      toast.error(
        t("attachments.tooMany", { max: attachments?.maxFiles ?? 1 })
      );
    } else if (error.code === "max_file_size") {
      toast.error(t("attachments.tooLarge"));
    } else {
      toast.error(t("attachments.unsupported"));
    }
  }

  return (
    <div
      className={
        compact ? "bg-background p-3 pt-2" : "bg-background px-4 pt-2 pb-4"
      }
    >
      <PromptInput
        className={compact ? "w-full" : "mx-auto max-w-3xl"}
        accept={attachments?.accept.join(",")}
        multiple={(attachments?.maxFiles ?? 1) !== 1}
        maxFiles={attachments?.maxFiles}
        maxFileSize={attachments?.maxBytes}
        globalDrop={Boolean(attachments) && !compact}
        onError={reportError}
        onSubmit={async ({ text, files }) => {
          const trimmed = text.trim();
          if ((!trimmed && files.length === 0) || isStreaming || disabled) {
            return;
          }
          let parts = files;
          if (attachments?.mode === "stored" && files.length > 0) {
            setUploading(true);
            try {
              parts = await Promise.all(
                files.map((file) =>
                  upload(file, attachments.uploadUrl ?? DEFAULT_UPLOAD_URL)
                )
              );
            } catch {
              toast.error(t("attachments.uploadFailed"));
              throw new Error("upload failed");
            } finally {
              setUploading(false);
            }
          }
          onSend(trimmed, parts, menu.mentions);
          menu.clearPicked();
        }}
      >
        {attachments ? (
          <PromptInputAttachments>
            {(file) => (
              <PromptInputAttachment
                key={file.id}
                data={file}
                removeLabel={t("attachments.remove")}
              />
            )}
          </PromptInputAttachments>
        ) : null}
        <PromptInputTextarea
          ref={textareaRef}
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={(event) => {
            if (menu.open && (event.key === "Escape" || event.key === "Tab")) {
              event.preventDefault();
              menu.close();
              return;
            }
            if (
              event.key === "ArrowUp" &&
              event.currentTarget.value === "" &&
              onEditLast
            ) {
              event.preventDefault();
              onEditLast();
            }
          }}
          onKeyUp={menu.refresh}
          onClick={menu.refresh}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={placeholder}
        />
        <PromptInputFooter>
          <PromptInputTools>
            {attachments ? (
              <PromptInputActionMenu>
                <PromptInputActionMenuTrigger
                  aria-label={t("attachments.add")}
                />
                <PromptInputActionMenuContent>
                  <PromptInputActionAddAttachments
                    label={t("attachments.add")}
                  />
                </PromptInputActionMenuContent>
              </PromptInputActionMenu>
            ) : null}
            <SpeechInput
              startLabel={t("composer.voiceStart")}
              stopLabel={t("composer.voiceStop")}
              onTranscript={(text, isFinal) => {
                if (!isFinal) return;
                const spoken = text.trim();
                if (!spoken) return;
                onChange(
                  value ? `${value.replace(/\s+$/, "")} ${spoken}` : spoken
                );
              }}
            />
            {models.length > 1 && modelId && onModelChange ? (
              <PromptInputSelect
                value={modelId}
                onValueChange={(next) => {
                  if (typeof next === "string") onModelChange(next);
                }}
              >
                <PromptInputSelectTrigger
                  size="sm"
                  aria-label={t("model.label")}
                >
                  <PromptInputSelectValue>
                    {(value: string) =>
                      models.find((model) => model.id === value)?.label ?? value
                    }
                  </PromptInputSelectValue>
                </PromptInputSelectTrigger>
                <PromptInputSelectContent>
                  {models.map((model) => (
                    <PromptInputSelectItem key={model.id} value={model.id}>
                      {model.label}
                    </PromptInputSelectItem>
                  ))}
                </PromptInputSelectContent>
              </PromptInputSelect>
            ) : null}
          </PromptInputTools>
          <PromptInputSubmit
            status={
              isStreaming ? "streaming" : uploading ? "submitted" : "ready"
            }
            label={isStreaming ? t("input.stop") : t("input.send")}
            disabled={!isStreaming && (disabled || uploading || !value.trim())}
            onClick={isStreaming ? onStop : undefined}
          />
        </PromptInputFooter>
      </PromptInput>
      <div className={compact ? "relative" : "relative mx-auto max-w-3xl"}>
        <ComposerMenu
          open={menu.open}
          options={menu.options}
          query={menu.query}
          onSelect={menu.select}
          emptyLabel={t("composer.noResults")}
        />
      </div>
      {compact ? null : (
        <p className="mx-auto mt-1 max-w-3xl px-1 text-xs text-muted-foreground">
          {t("input.hint")}
        </p>
      )}
    </div>
  );
}

"use client";

/**
 * Conversation header — the agent's name, the title with inline
 * rename, the consumer's `headerRight` slot, share, and delete.
 * History lives in the shell's sidebar (`ChatHistory`), which already
 * opens as a sheet on a phone.
 *
 * Under the app shell it renders into the shell header's
 * `shell-header-slot`, so the page has one bar, not two; anywhere
 * without that slot it is a header of its own.
 */

import { useState, useSyncExternalStore, useTransition } from "react";
import { createPortal } from "react-dom";
import { useTranslations } from "next-intl";
import { CheckIcon, PencilIcon, Trash2Icon, XIcon } from "lucide-react";
import { toast } from "sonner";

import { useRouter } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Spinner } from "@/components/ui/spinner";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

import { deleteConversation, renameConversation } from "@/actions/chat";
import { chatConfig } from "@/lib/chat-config";
import { ShareDialog } from "./share-dialog";

interface ConversationHeaderProps {
  conversationId: string;
  title: string | null;
}

export function ConversationHeader({
  conversationId,
  title,
}: ConversationHeaderProps) {
  const t = useTranslations("chat");
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [isEditing, setIsEditing] = useState(false);
  const [draftTitle, setDraftTitle] = useState(title ?? "");
  const slot = useSyncExternalStore(
    subscribeToNothing,
    findSlot,
    noSlotOnServer
  );
  const HeaderRight = chatConfig.headerRight;
  const agentName = chatConfig.agent?.name ?? t("agent.defaultName");
  const agentIcon = chatConfig.agent?.icon;

  function startEditing() {
    setDraftTitle(title ?? "");
    setIsEditing(true);
  }

  function commitRename() {
    const trimmed = draftTitle.trim();
    setIsEditing(false);
    if (!trimmed || trimmed === title) return;

    startTransition(async () => {
      const result = await renameConversation(conversationId, trimmed);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      router.refresh();
    });
  }

  function handleDelete() {
    startTransition(async () => {
      const result = await deleteConversation(conversationId);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      router.push("/chat");
      // The shell's history is rendered by the layout, which a
      // navigation does not re-render.
      router.refresh();
    });
  }

  const bar = (
    <div
      data-slot="conversation-header"
      className="flex min-w-0 flex-1 items-center justify-between gap-2"
    >
      <div className="flex min-w-0 flex-1 items-center gap-1">
        <span className="mr-1 flex shrink-0 items-center gap-1 text-xs text-muted-foreground">
          {agentIcon ? <span aria-hidden>{agentIcon}</span> : null}
          <span className="max-w-24 truncate">{agentName}</span>
        </span>
        {isEditing ? (
          <>
            <Input
              autoFocus
              aria-label={t("header.renameEdit")}
              value={draftTitle}
              onChange={(event) => setDraftTitle(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter") commitRename();
                if (event.key === "Escape") setIsEditing(false);
              }}
              className="h-8 max-w-xs"
            />
            <Button
              size="icon-sm"
              variant="ghost"
              className="shrink-0"
              onClick={commitRename}
              aria-label={t("header.renameSave")}
            >
              <CheckIcon />
            </Button>
            <Button
              size="icon-sm"
              variant="ghost"
              className="shrink-0"
              onClick={() => setIsEditing(false)}
              aria-label={t("header.renameCancel")}
            >
              <XIcon />
            </Button>
          </>
        ) : (
          <>
            <h1 className="truncate text-sm font-medium">
              {title || t("header.newChatTitle")}
            </h1>
            <Button
              size="icon-xs"
              variant="ghost"
              className="shrink-0"
              onClick={startEditing}
              aria-label={t("header.renameEdit")}
            >
              <PencilIcon />
            </Button>
          </>
        )}
      </div>

      <div className="flex shrink-0 items-center gap-2">
        {HeaderRight ? <HeaderRight conversationId={conversationId} /> : null}

        <ShareDialog conversationId={conversationId} />

        {/* Confirmed: deleting a conversation is unrecoverable. */}
        <AlertDialog>
          <AlertDialogTrigger
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                className="text-muted-foreground hover:text-destructive"
                disabled={isPending}
                aria-label={t("header.delete")}
              />
            }
          >
            {isPending ? <Spinner /> : <Trash2Icon />}
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>{t("deleteDialog.title")}</AlertDialogTitle>
              <AlertDialogDescription>
                {t("deleteDialog.description")}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>{t("deleteDialog.cancel")}</AlertDialogCancel>
              <AlertDialogAction onClick={handleDelete}>
                {t("deleteDialog.confirm")}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    </div>
  );

  // Undefined while rendering on the server and hydrating: the slot is
  // only known in the browser, and the bar appears once it is.
  if (slot === undefined) return null;
  if (slot) return createPortal(bar, slot);
  return (
    <header className="flex items-center border-b px-4 py-3">{bar}</header>
  );
}

const SLOT_SELECTOR = '[data-slot="shell-header-slot"]';

function subscribeToNothing() {
  return () => {};
}

function findSlot(): HTMLElement | null {
  return document.querySelector<HTMLElement>(SLOT_SELECTOR);
}

function noSlotOnServer(): undefined {
  return undefined;
}

/**
 * The conversation history for the shell's sidebar — bind it as
 * `sidebarContent` in `lib/shell-config.tsx`:
 *
 *   import { ChatHistory } from "@/components/chat/chat-history";
 *
 *   export const shellConfig: ShellConfig = { sidebarContent: ChatHistory };
 *
 * A server component: the list arrives with the page, and anything that
 * changes it — a new conversation's title, a rename, a delete — calls
 * `router.refresh()`, which renders it again.
 */

import { listConversationHistory } from "@/actions/chat";
import { ChatHistoryNav } from "./chat-history-nav";

export async function ChatHistory() {
  const result = await listConversationHistory();
  if (!result.success) return null;
  return <ChatHistoryNav conversations={result.data} />;
